37	/** One arrow, exactly as the rules layer writes one. */
38	export type Link = components["schemas"]["Link"];
39	
40	/** One rule broken, with the rule's own code and the rule's own sentence. */
41	export type Violation = components["schemas"]["Violation"];
42	
43	/** One finished world: a map with every likelihood worked through it. */
44	export type World = components["schemas"]["World"];
45	
46	/** The run has started. The first thing that arrives, and it arrives at once. */
47	export interface GenerationStarted {
48	  readonly event: "generation_started";
49	  /** The engine's name for this run. What the transcript is asked for by. */
50	  readonly generation_id: string;
51	  /**
52	   * The seed every random draw in this run came from — always a number here,
53	   * even when the request left it out. Whoever chose it, this event is where the
54	   * browser reads it: the one the request sent, or the one the engine minted when
55	   * it sent none, or, on a replay, the one in the recording's header, which wins
56	   * over both. The browser prints what this says and never works out which case
57	   * it was.
58	   */
59	  readonly seed: number;
60	  /**
61	   * The same seed, exactly as it was written on the wire.
62	   *
63	   * **Put here by the reader, not by the server**, like the `event` field above
64	   * — and for a reason worth writing down. A seed is a whole number the engine
65	   * draws with, and it can be nineteen digits long; JavaScript holds a whole
66	   * number exactly only up to sixteen, so `seed` above is already rounded by the
67	   * time any code here sees it. The run this build was first watched on drew with
68	   * 4 803 646 386 380 448 080, and the browser's own reading of that ends 000.
69	   *
70	   * The browser never computes with a seed — it prints it, so that a reader can
71	   * ask for the same map again — so the honest thing to print is the digits that
72	   * came off the wire. Absent only when a reader handed the events over by hand
73	   * rather than reading them from a stream.
74	   */
75	  readonly seed_as_written?: string;
76	  /** The sentence the reader typed, in their own words. */
77	  readonly hypothesis: string;
78	  /** The Verify door's destination, in their words. Null when they used the Explore door. */
79	  readonly target: string | null;
80	}
81	
82	/** One proposal the rules accepted. A claim, its incoming arrows, or both. */
83	export interface ProposalAccepted {
84	  readonly event: "proposal_accepted";
85	  /** Where this sits in the transcript, counting from 0. */
86	  readonly at: number;
87	  /** The new claim, with its identifier minted by the engine. Null for an arrows-only proposal. */
88	  readonly proposition: Proposition | null;
89	  /** Its incoming arrows, identifiers minted by the engine. */
90	  readonly links: readonly Link[];
91	  /** The claims still open to expand. What the reserved rectangles are drawn from. */
92	  readonly frontier: readonly PropositionId[];
93	}
