119	export interface Verdict {
120	  readonly event: "verdict";
121	  readonly kind: "reached" | "no_path";
122	  /** The steps of the path, in order. Empty on `no_path`. */
123	  readonly path: readonly PropositionId[];
124	  /** The multiplied-out likelihood of those steps. Null on `no_path`. */
125	  readonly product: number | null;
126	  /** On `no_path`: the closest claim the map did reach. */
127	  readonly nearest: PropositionId | null;
128	  /** One plain sentence, the engine's own. */
129	  readonly why: string;
130	}
131	
132	/** What the run cost. */
133	export interface Receipt {
134	  readonly event: "receipt";
135	  readonly model: string;
136	  readonly calls: number;
137	  readonly input_tokens: number;
138	  readonly output_tokens: number;
139	  readonly cache_read_tokens: number;
140	  /**
141	   * How many web searches this run made. Billed apart from tokens, so `dollars`
142	   * cannot be accounted for without it — which is why it is a field of its own
143	   * rather than something a reader is expected to infer.
144	   */
145	  readonly searches: number;
146	  readonly dollars: number;
147	  readonly seconds: number;
148	  /** Live, or played from a recording. The only place in the stream this is said. */
149	  readonly mode: "live" | "replay";
150	  /** The day the recording was made, as the map writes a day: `2026-09-18`. Null when live. */
151	  readonly recording_date: string | null;
152	  /** A fingerprint of the prompt this run was made against. Always known. */
153	  readonly prompt_hash: string;
154	}
155	
156	/** Why the generation stopped. Not whether the Verify door found anything — that is the verdict. */
157	export interface Done {
158	  readonly event: "done";
159	  readonly reason: StopReason;
160	  readonly claims: number;
161	  readonly links: number;
162	  readonly rejected: number;
163	}
164	
165	/** The seven reasons a generation stops. There is no eighth, and none of them is `no_path`. */
166	export type StopReason =
167	  | "reached_terminal"
168	  | "depth_cap"
169	  | "width_cap"
170	  | "claim_cap"
171	  | "spend_cap"
172	  | "refusal_cap"
173	  | "no_terminal";
174	
175	/** The run broke. One plain sentence, never a stack trace. */
176	export interface Failed {
177	  readonly event: "failed";
178	  readonly message: string;
179	}
180	
181	/** Any one of the eight. The `event` field is what a `switch` walks. */
182	export type StreamEvent =
183	  | GenerationStarted
184	  | ProposalAccepted
185	  | ProposalRejected
186	  | BeliefsPropagated
187	  | Verdict
188	  | Receipt
189	  | Done
190	  | Failed;
191	
192	/** The eight names, so a reader can tell one it knows from one it does not. */
193	export const EVENT_NAMES: readonly StreamEvent["event"][] = [
194	  "generation_started",
195	  "proposal_accepted",
196	  "proposal_rejected",
197	  "beliefs_propagated",
198	  "verdict",
199	  "receipt",
200	  "done",
201	  "failed",
202	];
203	
204	/**
205	 * An event whose name this build does not know.
206	 *
207	 * It is a shape of its own rather than a hole in the union: the reader has to
208	 * hand something back for every line on the wire, and a name with a payload
209	 * nobody can read is still a thing that happened. What is done with one is the
210	 * reducer's business — count it, change nothing else, and say so in the
211	 * transcript.
212	 */
213	export interface UnknownEvent {
214	  readonly event: "unknown";
215	  /** The name the wire carried. */
216	  readonly name: string;
217	}
218	
219	/** Everything the reader can hand back: one of the eight, or a name it does not know. */
220	export type ReadEvent = StreamEvent | UnknownEvent;
221	
222	/** What the browser asks for when it asks for a map. */
223	export interface GenerateRequest {
224	  /**
225	   * The sentence the reader typed — and, with no key, the whole of how the server
226	   * knows which recording to play. Required, and never empty.
227	   */
228	  readonly hypothesis: string;
229	  /** The Verify door's destination, in the reader's words. Absent is the Explore door. */
230	  readonly target?: string;
231	  /** The reader's own likelihood on the hypothesis. Absent when they chose "I don't know". */
232	  readonly user_belief?: Ranged;
233	  /**
234	   * Only when reproducing a run we were handed a seed for.
235	   *
236	   * **The browser does not invent one.** With none, the engine mints one and the
237	   * first event says which, so the run is reproducible from the moment it starts
238	   * and the number on screen is still the engine's.
239	   */
240	  readonly seed?: number;
241	}
