31	import { Outline } from "./components/Outline";
32	import { ReceiptStrip } from "./components/ReceiptStrip";
33	import { Refusal } from "./components/Refusal";
34	import { RefusalStrip } from "./components/RefusalStrip";
35	import { ReplayBadge, replaySentence } from "./components/ReplayBadge";
36	import { ShortcutsSheet } from "./components/ShortcutsSheet";
37	import { VerdictCard } from "./components/VerdictCard";
38	import "./components/generationDock.css";
39	import { MapCanvas } from "./graph/Canvas";
40	import { bothPaintings, type Engine, railRows } from "./graph/diff/branchWorld";
41	import { endings, NO_SUMMARY_YET } from "./graph/diff/endings";
42	import { roomFor } from "./graph/geometry";
43	import type { MapKeys } from "./keyboard/useMapKeys";
44	import { generate } from "./stream/generate";
45	import type { Growth } from "./stream/growth";
46	import { fold, waitingFor } from "./stream/growth";
47	import type { Readiness } from "./stream/readiness";
48	import { withRecordings } from "./stream/readiness";
49	import type { Working } from "./stream/transcript";
50	import { readTranscript } from "./stream/transcript";
51	import {
52	  type Absence,
53	  ApiWorldSource,
54	  appendEdit,
55	  type BranchView,
56	  branchesOf,
57	  type DiffView,
58	  type Edit,
59	  FixtureWorldSource,
60	  forkBranch,
61	  type Known,
62	  type LinkView,
63	  openBranch,
64	  type Ranged,
65	  type Reason,
66	  type Selection,
67	  type WorldSource,
68	  type WorldView,
69	  workshopOf,
70	} from "./world";
71	
72	/**
73	 * Everything the screen can know about one thing it asked for. Three states and
74	 * no others, which is what makes every pixel below traceable to a cause.
75	 */
76	type Answer<Reading> =
77	  | { state: "asking" }
78	  | { state: "answered"; value: Reading }
79	  | { state: "failed"; reason: string };
80	
81	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
82	type Tone = "good" | "quiet" | "loud";
83	
84	/** One row of the strip at the foot of the launchpad. */
85	interface Reading {
86	  /** What is being reported, such as "server". */
87	  label: string;
88	  /** The value from the server, or null while the request is still in flight. */
89	  value: string | null;
90	  /** A mark beside the words. Never the only carrier of meaning. */
91	  glyph: string;
92	  /** What the value means, in plain words. On a failure, this is the failure. */
93	  state: string;
94	  tone: Tone;
95	}
96	
97	/**
98	 * Whether the panel beside the map has more above and more below what it is
99	 * showing.
100	 *
101	 * **The panel measures itself.** It is the one scrolling thing on this screen,
102	 * and a reader has to be able to tell a control that is not there from a control
103	 * that is merely below the fold. A scrollbar cannot tell them: on a Mac it is an
104	 * overlay that fades in on a gesture, so it speaks only to somebody who is
105	 * already scrolling.
106	 *
107	 * It is watched three ways because the panel changes for three different
108	 * reasons: the reader scrolls it, a claim arrives and makes it taller, and the
109	 * window is resized and makes it shorter. Missing any one of them leaves a rule
110	 * drawn at an edge with nothing beyond it, which is the panel claiming something
111	 * a reader can check in one gesture.
112	 */
113	function useTheEdgesOfThePanel(): {
114	  panel: React.RefObject<HTMLElement | null>;
115	  above: boolean;
116	  below: boolean;
117	} {
118	  const panel = useRef<HTMLElement | null>(null);
119	  const [edges, setEdges] = useState({ above: false, below: false });
120	
121	  useEffect(() => {
122	    const it = panel.current;
123	    if (it === null) {
124	      return;
125	    }
126	    const measure = (): void => {
127	      // A pixel of slack, because a panel scrolled to its very end lands a
128	      // fraction short of its own height often enough to matter.
129	      const above = it.scrollTop > 1;
130	      const below = it.scrollTop + it.clientHeight < it.scrollHeight - 1;
131	      setEdges((was) => (was.above === above && was.below === below ? was : { above, below }));
132	    };
133	    measure();
134	    it.addEventListener("scroll", measure, { passive: true });
135	    // Watching a box change size is the browser's own job, and a page that
136	    // cannot do it — a simulated one in a test — still gets the scrolling half
137	    // rather than nothing at all.
138	    const watching =
139	      typeof ResizeObserver === "undefined" ? undefined : new ResizeObserver(measure);
140	    watching?.observe(it);
141	    for (const child of it.children) {
142	      watching?.observe(child);
143	    }
144	    return () => {
145	      it.removeEventListener("scroll", measure);
146	      watching?.disconnect();
147	    };
148	  });
149	
150	  return { panel, above: edges.above, below: edges.below };
151	}
152	
153	/** Turn whatever a failed request threw into one sentence. */
154	function inWords(reason: unknown): string {
155	  return reason instanceof Error ? reason.message : "The reason was not recorded.";
156	}
157	
158	/**
159	 * Ask what this copy can do, and read the list of recordings off the answer.
160	 *
161	 * Defined at module level because the hook below runs it once and needs the same
162	 * function on every render.
163	 */
164	function askReadiness(): Promise<Readiness> {
165	  return readReadiness().then(withRecordings);
166	}
167	
168	/**
169	 * Make one request when the screen first appears and report where it got to.
170	 *
171	 * @param ask The request to make. It must be the same function on every render,
172	 *   so pass one defined at module level rather than one written inline.
173	 */
174	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
175	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
176	
177	  useEffect(() => {
178	    let stillOnScreen = true;
179	    ask().then(
180	      (value) => {
181	        if (stillOnScreen) {
182	          setAnswer({ state: "answered", value });
183	        }
184	      },
185	      (reason: unknown) => {
186	        if (stillOnScreen) {
187	          setAnswer({ state: "failed", reason: inWords(reason) });
188	        }
189	      },
190	    );
191	    return () => {
192	      stillOnScreen = false;
193	    };
194	  }, [ask]);
195	
196	  return answer;
197	}
198	
199	/** The row that says whether the server answered at all. */
200	function serverReading(answer: Answer<Health>): Reading {
201	  switch (answer.state) {
202	    case "asking":
203	      return {
204	        label: "server",
205	        value: null,
206	        glyph: "○",
207	        state: "asking the server",
208	        tone: "quiet",
209	      };
210	    case "answered":
211	      return {
212	        label: "server",
213	        value: answer.value.status,
214	        glyph: "●",
215	        state: "reachable",
216	        tone: "good",
217	      };
218	    case "failed":
219	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
220	  }
221	}
222	
223	/** The row that says whether a key for the language model is configured. */
224	function modelKeyReading(answer: Answer<Readiness>): Reading {
225	  switch (answer.state) {
226	    case "asking":
227	      return {
228	        label: "model key",
229	        value: null,
230	        glyph: "○",
231	        state: "asking the server",
232	        tone: "quiet",
233	      };
234	    case "answered":
235	      return answer.value.model_key_present
236	        ? {
237	            label: "model key",
238	            value: "present",
239	            glyph: "●",
240	            state: "ready to generate",
241	            tone: "good",
242	          }
243	        : {
244	            label: "model key",
245	            value: "absent",
246	            glyph: "○",
247	            state:
248	              answer.value.replayable.length === 0
249	                ? "no key configured, and nothing recorded to play instead"
250	                : `no key configured — ${answer.value.replayable.length} example(s) play from recordings`,
251	            tone: "quiet",
252	          };
253	    case "failed":
254	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
255	  }
256	}
257	
258	/** The row that says which build answered. */
259	function versionReading(answer: Answer<About>): Reading {
260	  switch (answer.state) {
261	    case "asking":
262	      return {
263	        label: "version",
264	        value: null,
265	        glyph: "○",
266	        state: "asking the server",
267	        tone: "quiet",
268	      };
269	    case "answered":
270	      return {
271	        label: "version",
272	        value: answer.value.version,
273	        glyph: "●",
274	        state: `reported by ${answer.value.name}`,
275	        tone: "good",
276	      };
277	    case "failed":
278	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
279	  }
280	}
281	
282	/**
283	 * One row: a label, the value the server gave, and what that value means.
284	 *
285	 * While the value is missing the cell holds a bar of the same height, so the
286	 * row does not change size when the answer arrives. There is no spinner: a bar
287	 * where the value will land says the same thing without pretending to spin.
288	 */
289	function StatusRow({ reading }: { reading: Reading }) {
290	  const waiting = reading.value === null;
291	  return (
292	    <div className="status-row">
293	      <dt className="status-label">{reading.label}</dt>
294	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
295	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
296	      </dd>
297	      <dd className="status-state" data-tone={reading.tone}>
298	        <span className="glyph" aria-hidden="true">
299	          {reading.glyph}
300	        </span>
301	        <span className="state-words">{reading.state}</span>
302	      </dd>
303	    </div>
304	  );
305	}
306	
307	/** Which of the screens is showing. */
308	type Screen =
309	  | { at: "launchpad" }
310	  | { at: "opening"; id: string }
311	  /** A map being built in front of the reader, from a sentence they typed. */
312	  | { at: "growing"; asked: Asked }
313	  | {
314	      at: "map";
315	      world: WorldView;
316	      branches: readonly BranchView[];
317	      /**
318	       * Why the map on screen was read from the stored example rather than
319	       * worked out by the engine, or nothing when the engine answered.
320	       */
321	      insteadOfTheEngine: string | null;
322	    }
323	  | { at: "failed"; id: string; reason: string };
324	
325	/** How long the wires take to arrive, column by column, before the map settles. */
326	const WAVE_SETTLES_AFTER = 1200;
327	
328	/**
329	 * What stands where a likelihood would go while the engine is being asked for
330	 * one.
331	 *
332	 * The shared vocabulary has three ways of saying a number is not there, and
333	 * this is the third of them — *nothing has been computed* — because that is
334	 * exactly what is true while a question is in flight: the engine has been asked
335	 * and has not answered, so nothing has worked this number through the map
336	 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
337	 * on screen keeps its shape, the slots that will move say why they are empty,
338	 * and the line under the map says what has been asked for and where.
339	 */
340	const WHILE_ASKING: Absence = {
341	  kind: "no_engine",
342	  words: "no engine yet",
343	  reason:
344	    "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
345	    "has not answered. Nothing has worked this number through the map yet.",
346	};
347	
348	/**
349	 * What stands where a likelihood would go when the engine **refused** the
350	 * branch.
351	 *
352	 * Not "no engine yet": the engine is there and it answered — it said the branch
353	 * does not fit the map, and it said why. The words have to be true of that, and
354	 * the vocabulary's first three rows are all about a number nobody has worked out
355	 * rather than one that could not be. So there is a **fourth row** — *the engine
356	 * refused the branch these numbers would come from* → **not worked out** — and a
357	 * kind of its own to go with it, because "nothing has run yet" invites waiting
358	 * and "the engine turned this down" invites repairing what it turned down.
359	 */
360	const REFUSED: Absence = {
361	  kind: "refused",
362	  words: "not worked out",
363	  reason:
364	    "The engine would not work this map out from this branch: the branch does not fit the map. " +
365	    "Every reason is beside the map, and nothing on the map has changed.",
366	};
367	
368	/**
369	 * What stands there when the engine could not be reached at all.
370	 *
371	 * **Not a refusal**, and the difference is the whole of why the two are separate
372	 * kinds. A refusal is an answer: the engine looked, said no, and said why, and
373	 * it will say the same thing until the branch is repaired. This is one attempt
374	 * that did not come back — the engine is there and it was asked — and it stops
375	 * being true the moment the reader asks again. So it takes the kind that is
376	 * never kept, and its reason says what to do about it.
377	 */
378	function unreachable(reason: string): Absence {
379	  return {
380	    kind: "ask_failed",
381	    words: "the ask did not come back",
382	    reason: `${reason} Nothing on the map has changed; opening the branch again asks once more.`,
383	  };
384	}
385	
386	/**
387	 * Everything the engine has said about the branch that is open, and whether it
388	 * has said it yet.
389	 */
390	type Answered =
391	  | { at: "asking" }
392	  | { at: "answered"; computed: { now: WorldView; change: DiffView } }
393	  | { at: "refused"; reasons: readonly Reason[] }
394	  | { at: "failed"; reason: string }
395	  | { at: "nothing-open" };
396	
397	/**
398	 * Where the engine has got to, in the one shape the picture reads.
399	 *
400	 * Every state but *nothing is open* reserves the room an answer will take and
401	 * says why it is not there yet, so the map is the same size before and after the
402	 * answer lands and nothing on it jumps.
403	 */
404	function engineState(answer: Answered): Engine | undefined {
405	  switch (answer.at) {
406	    case "answered":
407	      return { at: "answered", now: answer.computed.now, change: answer.computed.change };
408	    case "asking":
409	      return { at: "waiting", absence: WHILE_ASKING };
410	    case "refused":
411	      return { at: "waiting", absence: REFUSED };
412	    case "failed":
413	      return { at: "waiting", absence: unreachable(answer.reason) };
414	    case "nothing-open":
415	      return undefined;
416	  }
417	}
418	
419	/** Turn whatever the engine threw into either a list of reasons or one sentence. */
420	function asAnswer(reason: unknown): Answered {
421	  if (reason instanceof RefusedBranch) {
422	    return { at: "refused", reasons: reason.reasons };
423	  }
424	  return { at: "failed", reason: inWords(reason) };
425	}
426	
427	/**
428	 * The map, the panel beside it, and everything you can do to both.
429	 *
430	 * Three things live here rather than inside the map, because all three are about
431	 * the whole screen rather than about the picture: which branch is open, which of
432	 * the two worlds is painted, and what the keyboard is on.
433	 */
434	function MapScreen({
435	  base,
436	  branches,
437	  source,
438	  insteadOfTheEngine,
439	  onLeave,
440	}: {
441	  base: WorldView;
442	  branches: readonly BranchView[];
443	  /** Where a branch's world, its difference and an arrow's number are asked for. */
444	  source: WorldSource;
445	  /** Why this map is the stored example rather than the engine's, or nothing. */
446	  insteadOfTheEngine: string | null;
447	  onLeave: () => void;
448	}) {
449	  const [shop, setShop] = useState(() => workshopOf(branches));
450	  const [showing, setShowing] = useState<"now" | "before">("now");
451	  const [selection, setSelection] = useState<Selection>(null);
452	  const [focused, setFocused] = useState<string | null>(null);
453	  const [dock, setDock] = useState<"panel" | "outline" | "away">("panel");
454	  const [onlyColumn, setOnlyColumn] = useState<{
455	    layer: number;
456	    claims: readonly string[];
457	  } | null>(null);
458	  const [overlay, setOverlay] = useState<"palette" | "sheet" | null>(null);
459	  const [intervening, setIntervening] = useState(false);
460	  const [naming, setNaming] = useState(false);
461	  const [status, setStatus] = useState(
462	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
463	  );
464	  const [arriving, setArriving] = useState(true);
465	  const lastBranch = useRef<string | null>(null);
466	  const { panel, above: moreAbove, below: moreBelow } = useTheEdgesOfThePanel();
467	
468	  const open = shop.branches.find((branch) => branch.id === shop.openId);
469	
470	  // What the engine says about the branch that is open. It is asked again
471	  // whenever the branch changes — which is what makes the six buttons move
472	  // numbers: pressing one appends an edit, and the whole branch goes back.
473	  const [answer, setAnswer] = useState<Answered>({ at: "nothing-open" });
474	  useEffect(() => {
475	    if (open === undefined) {
476	      setAnswer({ at: "nothing-open" });
477	      return;
478	    }
479	    let stillWanted = true;
480	    setAnswer({ at: "asking" });
481	    Promise.all([
482	      source.readWorld({ baseId: base.baseId, branch: open }),
483	      source.readDiff({ baseId: base.baseId, branch: open }),
484	    ]).then(
485	      ([now, change]) => {
486	        if (stillWanted) {
487	          setAnswer({ at: "answered", computed: { now, change } });
488	        }
489	      },
490	      (failure: unknown) => {
491	        if (stillWanted) {
492	          setAnswer(asAnswer(failure));
493	        }
494	      },
495	    );
496	    return () => {
497	      // An answer to a question the reader has moved on from is thrown away
498	      // rather than drawn: a map that flickers back to an older branch because
499	      // a slower request finished last is a map nobody can trust.
500	      stillWanted = false;
501	    };
502	    // The branch itself is what this hangs on, and that is enough: appending an
503	    // edit hands back a new branch rather than changing the one that was there
504	    // — a branch is an audit trail and nothing rewrites one — so every press of
505	    // a button is a new question here, and nothing else is.
506	  }, [source, base.baseId, open]);
507	
508	  // Held still between renders, because both paintings of the map hang on it: a
509	  // fresh object every render would lay the whole map out again on every keypress
510	  // for an answer that has not changed.
511	  const engine = useMemo(() => engineState(answer), [answer]);
512	  const computed = answer.at === "answered" ? answer.computed : undefined;
513	
514	  // The numbers on the arrows, one at a time, kept once they arrive. Each one
515	  // costs a whole extra run of the map, so it is asked for when a reader selects
516	  // that arrow and never again for the same branch, seed and arrow.
517	  const [wireNumbers, setWireNumbers] = useState<ReadonlyMap<string, Known<Ranged>>>(new Map());
518	  // The last ask that did not come back, which is shown and never kept. A
519	  // failure is a fact about one attempt, not about the number: keeping it would
520	  // mean the reader who selects the arrow again after the server comes back is
521	  // told for the rest of the session that it cannot be worked out.
522	  const [wireFailed, setWireFailed] = useState<{ key: string; absence: Absence } | undefined>();
523	  const paintings = useMemo(
