991	/**
992	 * Run one generation and fold what comes back into what the screen knows.
993	 *
994	 * **No component talks to the network**: this hook holds the one request, and
995	 * everything on screen is drawn from the state it folds. The run stops when the
996	 * reader leaves the page, which is what stops the spending — the route checks
997	 * whether the client is still there before its next model call.
998	 *
999	 * @param asked The sentence, the destination if there was one, and the reader's
1000	 *   own likelihood if they gave one.
1001	 */
1002	function useGeneration(asked: Asked): Growth {
1003	  const [growth, setGrowth] = useState<Growth>(() => waitingFor(asked.hypothesis, asked.target));
1004	
1005	  useEffect(() => {
1006	    const stop = new AbortController();
1007	    let stillOnScreen = true;
1008	    setGrowth(waitingFor(asked.hypothesis, asked.target));
1009	
1010	    const run = async (): Promise<void> => {
1011	      const stream = generate(
1012	        {
1013	          hypothesis: asked.hypothesis,
1014	          ...(asked.target === null ? {} : { target: asked.target }),
1015	          // "I don't know" sends nothing at all. Not a half, not a wide band.
1016	          ...(asked.belief === null ? {} : { user_belief: asked.belief }),
1017	        },
1018	        { signal: stop.signal },
1019	      );
1020	      for await (const event of stream) {
1021	        if (!stillOnScreen) {
1022	          return;
1023	        }
1024	        setGrowth((was) => fold(was, event));
1025	      }
1026	    };
1027	
1028	    run().catch((failure: unknown) => {
1029	      if (!stillOnScreen) {
1030	        return;
1031	      }
1032	      // Never reaching the route at all is the one thing that is not an event:
1033	      // there is no stream to read and nothing to draw, so it is folded in by
1034	      // hand as the sentence the failure arrived with.
1035	      setGrowth((was) => fold(was, { event: "failed", message: inWords(failure) }));
1036	    });
1037	
1038	    return () => {
1039	      stillOnScreen = false;
1040	      stop.abort();
1041	    };
1042	  }, [asked.hypothesis, asked.target, asked.belief]);
1043	
1044	  return growth;
1045	}
1046	
1047	/**
1048	 * The screen a map builds itself on.
1049	 *
1050	 * The same canvas, the same panel and the same keyboard as every other map. What
1051	 * is different is where the map comes from: it arrives claim by claim down one
1052	 * request, with a reserved rectangle standing wherever the next one will go, and
1053	 * every proposal the rules refused listed beside it.
1054	 *
1055	 * **There is no spinner here, and no moment where a blank screen turns into a
1056	 * finished picture.** The growing *is* the loading state.
1057	 */
