1108	  // The keyboard follows the growing edge: a claim that has just arrived takes
1109	  // focus, exactly as a claim a branch adds does. That is what keeps the newest
1110	  // tile on the glass through a run that goes on for minutes — the canvas
1111	  // already brings whatever the keyboard is on into view, so nothing here
1112	  // re-frames the map and nothing re-lays it out. A tile that is already placed
1113	  // stays exactly where it is; what moves is where the reader is looking.
1114	  // A claim that has just **arrived** takes focus, and nothing else does. The
1115	  // count is what says one arrived: when the likelihoods land, the engine's own
1116	  // world replaces the drawing and its claims come back in the map's order
1117	  // rather than the order they were proposed in — which is not an arrival, and
1118	  // moving the view for it would slide the map sideways at the very moment it
1119	  // stopped changing.
1120	  const howManyClaims = growth.world.claims.length;
1121	  const seenSoFar = useRef(0);
1122	  const lastArrived = useRef<string | null>(null);
1123	  useEffect(() => {
1124	    if (howManyClaims <= seenSoFar.current) {
1125	      return;
1126	    }
1127	    seenSoFar.current = howManyClaims;
1128	    const arrived = growth.world.claims[howManyClaims - 1]?.id ?? null;
1129	    lastArrived.current = arrived;
1130	    setFocused(arrived);
1131	  }, [howManyClaims, growth.world.claims]);
1132	
1133	  // And it lets go the moment the run stops. Focus is also what the hover lens
1134	  // reads, and a lens left on a claim the machine chose would dim the whole
1135	  // finished map to fifteen per cent at exactly the moment the reader starts
1136	  // reading it. If the reader has moved since, their focus is theirs and stays.
1137	  useEffect(() => {
1138	    if (!finished) {
1139	      return;
1140	    }
1141	    setFocused((was) => (was === lastArrived.current ? null : was));
1142	  }, [finished]);
1143	
1144	  const pick = useCallback((id: string) => {
1145	    setFocused(id);
1146	    setSelection({ kind: "claim", id });
1147	  }, []);
1148	
1149	  // Nothing on this screen is bound to the map's own six operations yet, so the
1150	  // keys that open them say so rather than doing nothing.
1151	  const keys: MapKeys = useMemo(
1152	    () => ({
1153	      intervene: () => setStatus("a generated map takes edits through Add a claim, beside the map"),
1154	      branch: () => setStatus("a branch is started on a stored map; this one is still being built"),
1155	      flipWorlds: () => setStatus("there is nothing to flip to — no branch is open"),
1156	      outline: () =>
1157	        setDock((was) => {
1158	          const next = was === "outline" ? "panel" : "outline";
1159	          setStatus(next === "outline" ? "the map as a list" : "the panel beside the map");
1160	          return next;
1161	        }),
1162	      panel: () => setStatus("the panel is beside the map"),
1163	      palette: () => setOverlay("sheet"),
1164	    }),
1165	    [],
1166	  );
1167	
1168	  return (
1169	    <main className="page page--map">
1170	      <header className="map-bar">
1171	        <button className="map-bar__back" type="button" onClick={onLeave}>
1172	          <span aria-hidden="true">←</span> Back to the launchpad
1173	        </button>
1174	        <h1 className="map-bar__title">{growth.world.title}</h1>
1175	        <p className="map-bar__where">
1176	          {/* Nothing sits over the map: the mark that says this run is a
1177	              recording is a badge up here, and the sentence explaining it is in
1178	              the line under the map with every other sentence about where this
1179	              map came from. */}
1180	          {replaying ? (
1181	            <ReplayBadge
1182	              recordingDate={growth.receipt?.recording_date ?? null}
1183	              receiptMode={growth.receipt?.mode ?? null}
1184	            />
1185	          ) : null}
1186	          {asked.target === null ? "Explore" : "Verify"}
1187	          <span className="map-bar__side">
1188	            {asked.target === null ? "what your sentence would cause" : asked.target}
1189	          </span>
1190	        </p>
1191	        <button className="map-bar__sheet" type="button" onClick={() => setOverlay("sheet")}>
1192	          Every key (?)
1193	        </button>
1194	      </header>
1195	
1196	      <div className="map-body">
1197	        <div className="map-stage">
1198	          <MapCanvas
1199	            world={growth.world}
1200	            selection={selection}
1201	            onSelect={setSelection}
1202	            focused={focused}
1203	            onFocused={setFocused}
1204	            mapKey={generationId ?? "a run that has not started"}
1205	            keys={keys}
1206	            onStatus={setStatus}
1207	            onOverflow={() => setStatus("every claim is in the list beside the map")}
1208	            arriving={!finished}
1209	            reserved={growth.skeletons}
1210	            // Framed once when the first rectangle is drawn, and once more when
1211	            // the run stops — the one moment nothing on the map is moving and
1212	            // the reader is about to start reading it.
1213	            frameAgainOn={finished ? "the run stopped" : undefined}
1214	          />
1215	          {overlay === "sheet" ? (
1216	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
1217	          ) : null}
1218	          <p className="map-status">
1219	            <span className="map-status__mark">last key</span>
1220	            {status}
1221	          </p>
1222	        </div>
1223	
1224	        <aside
1225	          className="dock dock--generation"
1226	          ref={panel}
1227	          data-more-above={moreAbove ? "yes" : "no"}
1228	          data-more-below={moreBelow ? "yes" : "no"}
1229	          aria-label="The panel beside the map"
1230	        >
1231	          {/* The map as a list, in place of the panel, exactly as it is on a
1232	              stored map: press O for it, press O again for the panel. It grows
1233	              as the map grows, in the same causal order, so a reader who never
1234	              sees the canvas hears the map being built rather than a silence
1235	              followed by a finished list. */}
1236	          {dock === "outline" ? (
1237	            <Outline items={outline} onPick={pick} focused={focused} />
1238	          ) : (
1239	            <>
1240	              {/* The Verify door's answer, at the top, when a destination was named. */}
1241	              {growth.verdict === null || asked.target === null ? null : (
1242	                <VerdictCard
1243	                  verdict={growth.verdict}
1244	                  target={asked.target}
1245	                  world={growth.world}
1246	                  onSelect={pick}
1247	                />
1248	              )}
1249	
1250	              <RefusalStrip
1251	                refusals={growth.refusals}
1252	                finished={finished}
1253	                openAt={openAt}
1254	                onOpen={(at) => {
1255	                  setOpenAt(at);
1256	                  setSelection({ kind: "generation", id: generationId ?? "" });
1257	                }}
1258	              />
1259	
1260	              {growth.receipt === null ? null : (
1261	                <ReceiptStrip
1262	                  receipt={growth.receipt}
1263	                  onOpen={() => {
1264	                    setOpenAt(null);
1265	                    setSelection({ kind: "generation", id: generationId ?? "" });
1266	                  }}
1267	                />
1268	              )}
1269	
1270	              {finished && growth.world.baseId !== "" ? (
1271	                // The same control, the same words and the same refusals as the
1272	                // one on a stored map's six-button panel. What differs is only
1273	                // what happens next: a generated map has no branch panel on this
1274	                // screen yet, so the claim is drafted, checked and said, and
1275	                // putting it on a branch of this map is the next piece of work.
1276	                <AddAClaim
1277	                  baseId={growth.world.baseId}
1278	                  andThen="It is checked against this map and ready to go onto a branch of it."
1279	                />
1280	              ) : null}
1281	
1282	              <Inspector
1283	                world={growth.world}
1284	                selection={selection}
1285	                generation={{
1286	                  receipt: growth.receipt,
1287	                  working,
1288	                  unknown: growth.unknown,
1289	                  openAt,
1290	                }}
1291	              />
1292	            </>
1293	          )}
1294	        </aside>
1295	      </div>
1296	
1297	      {/* Said out loud, and said once. On a stored map this line is on the page
1298	          as well; here the same facts are already drawn — the claims on the
1299	          canvas, the refusals in the panel, why the run stopped under the map —
1300	          so printing them again made the foot of the screen three strips of
1301	          prose saying the same thing twice. It stays the spoken channel. */}
1302	      <p className="map-live map-live--spoken" aria-live="polite">
1303	        {announcement}
1304	      </p>
1305	
1306	      <div className="map-origin">
1307	        <p className="map-origin__line">{growth.world.origin}</p>
1308	        {replaying ? (
1309	          <p className="map-origin__line">
1310	            {replaySentence({
1311	              recordingDate: growth.receipt?.recording_date ?? null,
1312	              receiptMode: growth.receipt?.mode ?? null,
1313	            })}
1314	          </p>
1315	        ) : null}
1316	        <DoneLine done={growth.done} failure={growth.failure} />
1317	        {(growth.world.warnings ?? []).map((warning) => (
1318	          <p className="map-origin__line" key={warning}>
1319	            {warning}
1320	          </p>
1321	        ))}
1322	      </div>
1323	    </main>
1324	  );
1325	}
1326	
1327	/**
1328	 * Where maps come from: the engine.
1329	 *
1330	 * Every number on the map is worked out by it, from the stored map, the branch
1331	 * and one seed. Nothing on this screen computes a likelihood, and nothing on
1332	 * this screen shows one the engine did not produce.
1333	 */
1334	const DEFAULT_SOURCE: WorldSource = new ApiWorldSource();
1335	
1336	/**
1337	 * Where maps come from when the engine cannot be reached.
1338	 *
1339	 * A map you can still read beats a blank screen. The stored example's claims,
1340	 * arrows, dates and sources are all real and all still worth reading — what is
1341	 * missing is the working-out, and the screen says so in a line under the map
1342	 * rather than letting a hand-written likelihood pass for a computed one.
1343	 */
1344	const FALLBACK_SOURCE: WorldSource = new FixtureWorldSource();
1345	
1346	/**
1347	 * The line under the map when the stored example is standing in for the engine.
1348	 *
1349	 * @param reason What went wrong, in the sentence the failure arrived with.
1350	 */
1351	function insteadOfTheEngine(reason: string): string {
1352	  return (
1353	    `The engine did not answer, so this map is the stored example exactly as it was written: ` +
1354	    `its claims, arrows, dates and sources are real, and its likelihoods are the illustrative ` +
1355	    `ones somebody wrote down rather than anything worked out. ${reason}`
1356	  );
1357	}
1358	
1359	/** What the screen needs. All three have defaults; all three exist so they can be swapped. */
1360	export interface AppProps {
1361	  /** Where maps and worlds come from. */
1362	  readonly source?: WorldSource;
1363	  /** Where they come from when the first one cannot answer. */
1364	  readonly fallback?: WorldSource;
1365	  /** How the list of stored examples is read. */
1366	  readonly listExamples?: () => Promise<FixtureSummary[]>;
1367	}
1368	
1369	/** The screen. */
1370	export function App({
1371	  source = DEFAULT_SOURCE,
1372	  fallback = FALLBACK_SOURCE,
1373	  listExamples = readExampleList,
1374	}: AppProps = {}) {
1375	  const health = useAnswer(readHealth);
1376	  const readiness = useAnswer(askReadiness);
1377	  const about = useAnswer(readAbout);
1378	  const examples = useAnswer(listExamples);
1379	
1380	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
1381	  const [using, setUsing] = useState<WorldSource>(source);
1382	
1383	  const open = useCallback(
1384	    (id: string) => {
1385	      setScreen({ at: "opening", id });
1386	      /**
1387	       * The world and the map's own branches, together: the world is what gets
1388	       * drawn, and the branches are the edits somebody already made to it, which
1389	       * the panel lists and the diff view folds on.
1390	       *
1391	       * @param from Where to ask.
1392	       */
1393	      const ask = (from: WorldSource) =>
1394	        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);
1395	
1396	      ask(source).then(
1397	        ([world, bundle]) => {
1398	          setUsing(source);
1399	          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
1400	        },
1401	        (failure: unknown) => {
1402	          // The engine could not answer. Rather than a blank screen, the stored
1403	          // example — and a line under the map saying, in the failure's own
1404	          // words, that these are not computed numbers.
1405	          ask(fallback).then(
1406	            ([world, bundle]) => {
1407	              setUsing(fallback);
1408	              setScreen({
1409	                at: "map",
1410	                world,
1411	                branches: branchesOf(bundle),
1412	                insteadOfTheEngine: insteadOfTheEngine(inWords(failure)),
1413	              });
1414	            },
1415	            // Neither answered, which means the server itself is not there. That
1416	            // is one sentence on the page, and a way back to the launchpad.
1417	            (alsoFailed: unknown) => setScreen({ at: "failed", id, reason: inWords(alsoFailed) }),
1418	          );
1419	        },
1420	      );
1421	    },
1422	    [source, fallback],
1423	  );
1424	
1425	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
1426	
1427	  /** Build a map from a sentence, and watch it arrive. */
1428	  const build = useCallback((asked: Asked) => setScreen({ at: "growing", asked }), []);
1429	
1430	  const readings = useMemo(
1431	    () => [serverReading(health), modelKeyReading(readiness), versionReading(about)],
1432	    [health, readiness, about],
1433	  );
1434	
1435	  if (screen.at === "growing") {
1436	    return (
1437	      <GenerationScreen
1438	        asked={screen.asked}
1439	        // Known before the stream has said anything, which is the whole reason
1440	        // the badge can be on screen from the first frame. When the receipt
1441	        // arrives it is the authority, and the badge takes its word.
1442	        replaying={readiness.state === "answered" && !readiness.value.model_key_present}
1443	        onLeave={toLaunchpad}
1444	      />
1445	    );
1446	  }
1447	
1448	  if (screen.at === "map") {
1449	    return (
1450	      <MapScreen
1451	        base={screen.world}
1452	        branches={screen.branches}
1453	        source={using}
1454	        insteadOfTheEngine={screen.insteadOfTheEngine}
1455	        onLeave={toLaunchpad}
1456	      />
1457	    );
1458	  }
1459	
1460	  if (screen.at !== "launchpad") {
1461	    return (
1462	      <main className="page page--map">
1463	        <header className="map-bar">
1464	          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
1465	            <span aria-hidden="true">←</span> Back to the launchpad
1466	          </button>
1467	          <h1 className="map-bar__title">Strait of Hormuz</h1>
1468	        </header>
1469	
1470	        <div className="map-waiting">
1471	          <p className="map-waiting__line">
1472	            {screen.at === "opening"
1473	              ? `Reading the map from /api/fixtures/${screen.id} and asking /api/worlds to work ` +
1474	                `its likelihoods through.`
1475	              : screen.reason}
1476	          </p>
1477	        </div>
1478	      </main>
1479	    );
1480	  }
1481	
1482	  return (
1483	    <main className="page">
1484	      {/* The first screen is the one wide column in this product: it holds the
1485	          two doors, a map that is already drawn, the four sentences from the
1486	          brief and the field you type your own into, and stacking all of that
1487	          in the 660-pixel measure the rest of the page reads at pushes the
1488	          field below the fold. `launchpad.css` owns the width. */}
1489	      <div className="column column--launchpad">
1490	        <header className="masthead">
1491	          <h1 className="wordmark">Katalyst</h1>
1492	          <p className="purpose">
1493	            Type an event you think will happen. See what it would cause, step by step, ending in
1494	            trades.
1495	          </p>
1496	        </header>
1497	
1498	        <Launchpad
1499	          examples={examples.state === "answered" ? examples.value : null}
1500	          failure={examples.state === "failed" ? examples.reason : null}
1501	          readiness={readiness.state === "answered" ? readiness.value : null}
1502	          onOpen={open}
1503	          onBuild={build}
1504	        />
1505	
1506	        <section aria-labelledby="status-heading">
1507	          <h2 className="section-heading" id="status-heading">
1508	            What this build can do right now
1509	          </h2>
1510	          <dl className="status-strip">
1511	            {readings.map((reading) => (
1512	              <StatusRow key={reading.label} reading={reading} />
1513	            ))}
1514	          </dl>
1515	          <p className="provenance">
1516	            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
1517	            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
1518	            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
1519	          </p>
1520	        </section>
1521	      </div>
1522	    </main>
1523	  );
1524	}
