1	/**
2	 * **Add a claim** — the one thing a reader can do to a map that needs the model.
3	 *
4	 * *"…but this also happens"*. It asks for **one** intervention: a claim and its
5	 * arrows, already drafted and already checked by the same rules every proposal
6	 * passes. It is not a generation — no stream and no reserved rectangle — but it
7	 * **is** several model calls, so it carries a receipt of its own, drawn by the
8	 * same strip a generation's receipt is drawn by.
9	 *
10	 * **The field is `position`, not `at`.** `at` already means a place in a
11	 * transcript on a stream event and a date on an edit, and a word that means three
12	 * things is a word that means none.
13	 *
14	 * **With no key, one sentence works and every other is declined in plain words.**
15	 * Each recording carries the one scripted intervention its card offers, matched
16	 * on the exact words after trimming surrounding spaces — the same rule that picks
17	 * which recording plays. There is no fuzzy matching and there will not be: a
18	 * similarity score doing the model's job badly would be a piece of state nobody
19	 * could trace to an input, a rule or a source. Anything else comes back declined,
20	 * and the control says so rather than disappearing.
21	 *
22	 * The other five things a reader can do — *Suppose this is true*, *This
23	 * happened*, *Change this push*, *Split this claim*, *My own number* — call no
24	 * model at all. They are arithmetic in the engine's pure core, which is why a
25	 * reader with no key still gets the whole multiverse at full fidelity.
26	 */
27	
28	import type { components } from "../api/schema";
29	import type { Receipt } from "./events";
30	import { INSERT_ADDRESS } from "./generate";
31	
32	/** One claim and its arrows, arriving as a single edit. */
33	export type DraftedClaim = components["schemas"]["Insert"];
34	
35	/**
36	 * What one drafted claim cost.
37	 *
38	 * **An insert is several model calls, not one**, so it carries a receipt of its
39	 * own — the same nine readings a generation's receipt carries, and drawn by the
40	 * same strip, because a cost shown two ways is two costs. It is what closes the
41	 * chapter's third open question: the route answers with a receipt beside the
42	 * intervention rather than the session growing a running total, which would be
43	 * the first number in this product added up by something other than the engine.
44	 */
45	export type InsertReceipt = Receipt;
46	
47	/** What it takes to ask for one. */
48	export interface DraftRequest {
49	  /** The map the new claim is going onto. */
50	  readonly base_id: string;
51	  /** What the reader typed. */
52	  readonly claim_in_words: string;
53	  /** Where in the branch the new edit goes. */
54	  readonly position?: number;
55	}
56	
57	/** How the ask turned out. Three answers, and a refusal is one of them. */
58	export type Drafted =
59	  | {
60	      readonly state: "drafted";
61	      readonly insert: DraftedClaim;
62	      /** What drafting it cost, when the route says. Null on a route that does not yet. */
63	      readonly receipt: InsertReceipt | null;
64	    }
65	  /** The rules would not have it, with every reason at once, in their own words. */
66	  | { readonly state: "refused"; readonly reasons: readonly string[] }
67	  /** It could not be drafted at all. One plain sentence, the server's own. */
68	  | { readonly state: "declined"; readonly reason: string };
69	
70	/**
71	 * Ask for one claim to be drafted and checked.
72	 *
73	 * @param request The map, the sentence and where the edit goes.
74	 * @param ask The function that makes the request. The browser's own by default.
75	 */
76	export async function draftAClaim(
77	  request: DraftRequest,
78	  ask: typeof globalThis.fetch = globalThis.fetch,
79	): Promise<Drafted> {
80	  let answer: Response;
81	  try {
82	    answer = await ask(INSERT_ADDRESS, {
83	      method: "POST",
84	      headers: { "content-type": "application/json" },
85	      body: JSON.stringify({ position: 0, ...request }),
86	    });
87	  } catch {
88	    return {
89	      state: "declined",
90	      reason: `Could not reach the server at ${INSERT_ADDRESS}. It may not be running.`,
91	    };
92	  }
93	
94	  const body = (await answer.json().catch(() => null)) as unknown;
95	  if (answer.ok) {
96	    // **Two shapes, one reading.** The route is moving to answering with the
97	    // drafted claim *and* what drafting it cost — an insert is several model
98	    // calls, and a cost nobody is shown is a cost nobody can check. Until every
99	    // copy answers that way, a body that is the claim on its own is still read,
100	    // and the cost is then absent rather than invented.
101	    const both = body as { insert?: DraftedClaim; receipt?: InsertReceipt } | null;
102	    if (both?.insert !== undefined) {
103	      return { state: "drafted", insert: both.insert, receipt: both.receipt ?? null };
104	    }
105	    return { state: "drafted", insert: body as DraftedClaim, receipt: null };
106	  }
107	
108	  const detail = (body as { detail?: unknown } | null)?.detail;
109	  // Every reason at once, in the rules' own sentences. A person fixing one fault
110	  // per attempt learns only that the tool is hostile.
111	  if (Array.isArray(detail)) {
112	    return {
113	      state: "refused",
114	      reasons: detail.map((one) =>
115	        typeof (one as { message?: unknown }).message === "string"
116	          ? String((one as { message: string }).message)
117	          : "The server would not carry this out and did not say why.",
118	      ),
119	    };
120	  }
121	  // The server's own plain sentence, printed word for word. With no key that is
122	  // *"drafting a new claim needs a model key."* and nothing else.
123	  return {
124	    state: "declined",
125	    reason:
126	      typeof detail === "string"
127	        ? detail
128	        : `The request to ${INSERT_ADDRESS} came back with no reading. The reply was numbered ${answer.status}.`,
129	  };
130	}
