/**
 * The working of one generation, read back after the map is drawn.
 *
 * A map is the answer; the transcript is the working. Every proposal, accepted or
 * refused, in the order it happened, with the rules' own sentences beside the
 * ones that were refused — and the lines where the model said a part of the story
 * was finished, which make no event on the stream because nothing about the map
 * changed, and which are the one thing a reader would otherwise never see.
 *
 * **Typed by hand, like the eight events, and for the same reason**: the server's
 * description of itself and this canvas are built at the same time. A later pull
 * request pins the two against each other.
 *
 * **It lives for the life of the server process.** There is no storage in this
 * stack, so a restart is enough to lose one — and when that has happened the
 * route says so in a plain sentence, which is printed as it came rather than
 * turned into an empty section a reader would read as a run that proposed
 * nothing.
 */

import type { Violation } from "./events";
import { transcriptAddress } from "./generate";

/** One thing that was proposed, and what happened to it. */
export interface TranscriptLine {
  /**
   * Where this sits on the stream, counting from 0 across accepted and refused
   * proposals together. **Null on a line that made no event**, which is how the
   * gaps in the stream's numbering are explained.
   */
  readonly at: number | null;
  /** What happened to it. Three kinds of line and no others. */
  readonly what: "accepted" | "refused" | "stopped";
  /** The claim the call was asking about, when it was asking about one. */
  readonly about: string | null;
  /** What the model wrote: the claim, the arrow's reason, or the sentence closing a line. */
  readonly in_words: string;
  /** Every reason the map's own rules gave, in their words. Empty unless refused. */
  readonly violations: readonly Violation[];
}

/** The whole working of one generation, in the order it happened. */
export interface Transcript {
  readonly generation_id: string;
  readonly hypothesis: string;
  readonly target: string | null;
  readonly seed: number;
  /** The day this generation ran, which is its map's day zero. */
  readonly on: string;
  readonly mode: "live" | "replay";
  readonly lines: readonly TranscriptLine[];
}

/** How the working turned out to be readable, or the plain reason it was not. */
export type Working =
  | { readonly state: "reading" }
  | { readonly state: "read"; readonly transcript: Transcript }
  | { readonly state: "gone"; readonly reason: string };

/**
 * Read the working of one generation back.
 *
 * @param generationId The identifier the stream's first event carried.
 * @param ask The function that makes the request. The browser's own by default.
 */
export async function readTranscript(
  generationId: string,
  ask: typeof globalThis.fetch = globalThis.fetch,
): Promise<Working> {
  const address = transcriptAddress(generationId);
  let answer: Response;
  try {
    answer = await ask(address);
  } catch {
    return {
      state: "gone",
      reason: `Could not reach the server at ${address}. It may not be running.`,
    };
  }
  if (!answer.ok) {
    // The server's own sentence when it no longer holds this generation, printed
    // as it came. A transcript lives for the life of the process that made it.
    const body = (await answer.json().catch(() => null)) as { detail?: unknown } | null;
    const said = typeof body?.detail === "string" ? body.detail : null;
    return {
      state: "gone",
      reason:
        said ??
        `The working of this run could not be read at ${address}. The reply was numbered ${answer.status}.`,
    };
  }
  return { state: "read", transcript: (await answer.json()) as Transcript };
}

/**
 * The way in: type a sentence, and watch what it would cause.
 *
 * **Three fields, one button, and no more.**
 *
 *   1. The sentence — the hypothesis, in the reader's own words.
 *   2. Where it ends, optional. This is the Verify door, and it is **one extra
 *      field rather than a second screen**.
 *   3. The reader's own likelihood, with an explicit *I don't know* state.
 *
 * **The button is "Build the map", word for word, on both doors.** Not
 * *Generate*, which is the pipeline's word rather than the reader's, and not
 * *Explore* or *Verify*, which are the two doors and are already named by whether
 * the second field has anything in it — a button whose label changed as the
 * reader typed would be a control that moved under them.
 *
 * **"I don't know" is a state of the control, not a value.** It is where the
 * control starts, and while it holds, the request carries **no** likelihood at
 * all — not a `.5`, not a wide band, not a null that something downstream treats
 * as a half. A reader who has not said what they think has not said what they
 * think, and a tool that fills that in for them has invented the one number it
 * had no business inventing.
 *
 * **With no model key the bar is visibly disabled and says why**, in the same
 * sentence the launchpad carries. Never silently inert: a field that takes typing
 * and then does nothing reads as a broken tool, where a field that says why reads
 * as an unfinished one, and only one of those is true.
 *
 * Nothing here computes anything. The three numbers the slider holds are the
 * three the reader put there; keeping them in order is a comparison, and the
 * guard that stops the control posting a certainty is a bound on the track.
 */

import { useId, useState } from "react";
import type { Ranged } from "../world";
import { toReading } from "./BeliefChip";
import "./inputBar.css";

/** What a reader asked for when they pressed the button. */
export interface Asked {
  /** The sentence they typed. Never empty: the button does not work without one. */
  readonly hypothesis: string;
  /** Where they said it ends, or nothing at all on the Explore door. */
  readonly target: string | null;
  /**
   * Their own likelihood, or nothing at all while the control is on *I don't
   * know*. Nothing at all is not a half.
   */
  readonly belief: Ranged | null;
}

/** What the bar needs to draw itself. */
export interface InputBarProps {
  /**
   * Why nothing can be built from a sentence right now, in one sentence, or null
   * when it can.
   *
   * It is read from the server's own answer about itself rather than written into
   * the page, so the reason on screen is the real one.
   */
  readonly disabledBecause: string | null;
  /** Start a generation. */
  readonly onBuild: (asked: Asked) => void;
}

/**
 * The bottom and the top of the track.
 *
 * A likelihood of exactly 1 is a certainty, and this product does not print one:
 * the chip prints `>.99` instead, and a control that could post a `1.0` would
 * make that guard a lie about where the number came from. So the track stops one
 * step short at each end, and every step on it is a two-significant-figure value.
 */
const FLOOR = 0.01;
const CEILING = 0.99;
const STEP = 0.01;

/** Where the three handles start, once the reader turns the control on. */
const OPENING: Ranged = { p: 0.5, lo: 0.3, hi: 0.7 };

/** Keep the three in order: the bottom is never above the number, the top never below it. */
function inOrder(belief: Ranged): Ranged {
  const p = Math.min(CEILING, Math.max(FLOOR, belief.p));
  return {
    p,
    lo: Math.min(p, Math.max(FLOOR, belief.lo)),
    hi: Math.max(p, Math.min(CEILING, belief.hi)),
  };
}

/** The way in. */
export function InputBar({ disabledBecause, onBuild }: InputBarProps) {
  const sentenceId = useId();
  const targetId = useId();
  const [hypothesis, setHypothesis] = useState("");
  const [target, setTarget] = useState("");
  // Null is *I don't know*, and it is where the control starts. It is a state of
  // the control rather than a value, so it is held as the absence of one.
  const [belief, setBelief] = useState<Ranged | null>(null);
  const off = disabledBecause !== null;
  const ready = hypothesis.trim() !== "";

  const handle = (over: Partial<Ranged>): void => {
    setBelief((was) => inOrder({ ...(was ?? OPENING), ...over }));
  };

  return (
    <form
      className="input-bar"
      data-disabled={off ? "yes" : "no"}
      onSubmit={(event) => {
        event.preventDefault();
        if (off || !ready) {
          return;
        }
        onBuild({
          hypothesis: hypothesis.trim(),
          target: target.trim() === "" ? null : target.trim(),
          belief,
        });
      }}
    >
      <div className="input-bar__field">
        <label className="input-bar__label" htmlFor={sentenceId}>
          An event you think will happen
        </label>
        <input
          className="input-bar__text"
          id={sentenceId}
          type="text"
          autoComplete="off"
          disabled={off}
          placeholder="The Strait of Hormuz is going to open next week."
          value={hypothesis}
          onChange={(event) => setHypothesis(event.target.value)}
        />
      </div>

      <div className="input-bar__field">
        <label className="input-bar__label" htmlFor={targetId}>
          Where you think it ends — optional
        </label>
        <input
          className="input-bar__text"
          id={targetId}
          type="text"
          autoComplete="off"
          disabled={off}
          placeholder="A Polymarket contract on Brent below $70"
          value={target}
          onChange={(event) => setTarget(event.target.value)}
        />
        <p className="input-bar__hint">
          Fill this in and the map is graded against it: the route, or a plain statement that none
          reaches it.
        </p>
      </div>

      <fieldset className="input-bar__belief" disabled={off}>
        <legend className="input-bar__label">How likely you think it is</legend>

        {belief === null ? (
          <div className="input-bar__unsaid">
            <p className="input-bar__reading" data-reading="unsaid">
              I don&rsquo;t know
            </p>
            <p className="input-bar__hint">
              Nothing is sent for this. A number put here for you would be the one number on the map
              nobody asked for.
            </p>
            <button
              className="input-bar__say"
              type="button"
              onClick={() => setBelief(inOrder(OPENING))}
            >
              Give my own number
            </button>
          </div>
        ) : (
          <div className="input-bar__track">
            <p className="input-bar__reading" data-reading="said">
              {toReading(belief.p, belief.lo, belief.hi)}
            </p>
            <label className="input-bar__handle">
              <span className="input-bar__handle-name">how likely</span>
              <input
                type="range"
                min={FLOOR}
                max={CEILING}
                step={STEP}
                value={belief.p}
                onChange={(event) => handle({ p: Number(event.target.value) })}
              />
            </label>
            <label className="input-bar__handle">
              <span className="input-bar__handle-name">bottom of the range</span>
              <input
                type="range"
                min={FLOOR}
                max={CEILING}
                step={STEP}
                value={belief.lo}
                onChange={(event) => handle({ lo: Number(event.target.value) })}
              />
            </label>
            <label className="input-bar__handle">
              <span className="input-bar__handle-name">top of the range</span>
              <input
                type="range"
                min={FLOOR}
                max={CEILING}
                step={STEP}
                value={belief.hi}
                onChange={(event) => handle({ hi: Number(event.target.value) })}
              />
            </label>
            <p className="input-bar__hint">
              The range says how sure you are of your own number, not how much the world can move.
              It sits beside the model&rsquo;s and a market&rsquo;s, and is never averaged with
              them.
            </p>
            <button className="input-bar__say" type="button" onClick={() => setBelief(null)}>
              Back to &ldquo;I don&rsquo;t know&rdquo;
            </button>
          </div>
        )}
      </fieldset>

      <div className="input-bar__go">
        <button className="input-bar__build" type="submit" disabled={off || !ready}>
          Build the map
        </button>
        {off ? (
          <p className="input-bar__why">{disabledBecause}</p>
        ) : ready ? null : (
          <p className="input-bar__why">
            Type an event above and this builds a map of what it would cause.
          </p>
        )}
      </div>
    </form>
  );
}

