1	/**
2	 * **Add a claim** — *"…but this also happens"*.
3	 *
4	 * The one thing a reader can do to a map that needs the model. It asks for one
5	 * intervention: a claim and its arrows, already drafted and already checked by
6	 * the same rules every proposal passes. It is not a generation — no stream, no
7	 * reserved rectangle, no receipt — and what it cost appears nowhere, which is an
8	 * open question the chapter records rather than a thing this control should
9	 * guess at.
10	 *
11	 * **It is never silently inert.** When it cannot draft — no key and no recorded
12	 * intervention for what was typed — the server says so in one plain sentence and
13	 * this control prints that sentence rather than disappearing. A control that
14	 * vanishes teaches a reader that they imagined it; a control that says why teaches
15	 * them what this copy can do.
16	 *
17	 * The other five things a reader can do to a map call no model at all. They are
18	 * arithmetic in the engine's pure core, which is why a reader with no key still
19	 * gets the whole multiverse at full fidelity.
20	 */
21	
22	import { useId, useState } from "react";
23	import type { Drafted, DraftedClaim } from "../stream/insert";
24	import { draftAClaim } from "../stream/insert";
25	import { ReceiptStrip } from "./ReceiptStrip";
26	import "./addAClaim.css";
27	
28	/** What the control needs to draw itself. */
29	export interface AddAClaimProps {
30	  /** The map the new claim would go onto. */
31	  readonly baseId: string;
32	  /** Where in the branch the new edit goes: the number of edits already in it. */
33	  readonly position?: number;
34	  /** What to do with a claim that was drafted and passed the rules. */
35	  readonly onDrafted?: (drafted: DraftedClaim) => void;
36	  /**
37	   * One line about what happens to a claim once it is drafted, in the words of
38	   * the screen this control is on. Beside a stored map it goes onto the branch;
39	   * beside a map that has just been generated there is no branch panel yet.
40	   */
41	  readonly andThen: string;
42	  /** How the request is made. The real one by default; a test hands in its own. */
43	  readonly draft?: typeof draftAClaim;
44	}
45	
46	/** *"…but this also happens"*. */
47	export function AddAClaim({
48	  baseId,
49	  position = 0,
50	  onDrafted,
51	  andThen,
52	  draft = draftAClaim,
53	}: AddAClaimProps) {
54	  const fieldId = useId();
55	  const [words, setWords] = useState("");
56	  const [asking, setAsking] = useState(false);
57	  const [answer, setAnswer] = useState<Drafted | null>(null);
58	
59	  return (
60	    <section className="add-a-claim" aria-label="Add a claim to this map">
61	      <h3 className="add-a-claim__heading">Add a claim</h3>
62	      <form
63	        className="add-a-claim__form"
64	        onSubmit={(event) => {
65	          event.preventDefault();
66	          if (asking || words.trim() === "") {
67	            return;
68	          }
69	          setAsking(true);
70	          setAnswer(null);
71	          draft({ base_id: baseId, claim_in_words: words.trim(), position }).then((drafted) => {
72	            setAsking(false);
73	            setAnswer(drafted);
74	            if (drafted.state === "drafted") {
75	              onDrafted?.(drafted.insert);
76	            }
77	          });
78	        }}
79	      >
80	        <label className="add-a-claim__label" htmlFor={fieldId}>
81	          …but this also happens
82	        </label>
83	        <input
84	          className="add-a-claim__text"
85	          id={fieldId}
86	          type="text"
87	          autoComplete="off"
88	          placeholder="…but Iran is struck the next day"
89	          value={words}
90	          onChange={(event) => setWords(event.target.value)}
91	        />
92	        <button className="add-a-claim__ask" type="submit" disabled={asking || words.trim() === ""}>
93	          {asking ? "Drafting the claim" : "Draft this claim"}
94	        </button>
95	      </form>
96	
97	      {asking ? (
98	        <p className="add-a-claim__line">
99	          {/* Not a spinner: the shape of the thing being waited for, said in
100	              words. One claim is being drafted and checked against this map. */}
101	          One claim is being drafted and checked against this map, by the same rules every proposal
102	          passes.
103	        </p>
104	      ) : null}
105	
106	      {answer === null ? null : answer.state === "declined" ? (
107	        // The server's own sentence, word for word. With no key that is
108	        // "drafting a new claim needs a model key." and nothing else.
109	        <p className="add-a-claim__line" data-answer="declined">
110	          {answer.reason}
111	        </p>
112	      ) : answer.state === "refused" ? (
113	        <div className="add-a-claim__line" data-answer="refused">
114	          <p className="add-a-claim__refused">
115	            The map&rsquo;s own rules would not take this claim, and gave every reason at once.
116	          </p>
117	          <ul className="add-a-claim__reasons">
118	            {answer.reasons.map((reason) => (
119	              <li key={reason}>{reason}</li>
120	            ))}
121	          </ul>
122	        </div>
123	      ) : (
124	        <div className="add-a-claim__line" data-answer="drafted">
125	          <p className="add-a-claim__drafted">
126	            {`Drafted and checked: "${answer.insert.proposition.claim}" ${andThen}`}
127	          </p>
128	          {/* What drafting it cost, in the same nine readings and the same strip
129	              a generation's receipt is printed in. Absent on a copy of the route
