/**
 * **Add a claim** — *"…but this also happens"*.
 *
 * The one thing a reader can do to a map that needs the model. It asks for one
 * intervention: a claim and its arrows, already drafted and already checked by
 * the same rules every proposal passes. It is not a generation — no stream, no
 * reserved rectangle, no receipt — and what it cost appears nowhere, which is an
 * open question the chapter records rather than a thing this control should
 * guess at.
 *
 * **It is never silently inert.** When it cannot draft — no key and no recorded
 * intervention for what was typed — the server says so in one plain sentence and
 * this control prints that sentence rather than disappearing. A control that
 * vanishes teaches a reader that they imagined it; a control that says why teaches
 * them what this copy can do.
 *
 * The other five things a reader can do to a map call no model at all. They are
 * arithmetic in the engine's pure core, which is why a reader with no key still
 * gets the whole multiverse at full fidelity.
 */

import { useId, useState } from "react";
import type { Drafted, DraftedClaim } from "../stream/insert";
import { draftAClaim } from "../stream/insert";
import { ReceiptStrip } from "./ReceiptStrip";
import "./addAClaim.css";

/** What the control needs to draw itself. */
export interface AddAClaimProps {
  /** The map the new claim would go onto. */
  readonly baseId: string;
  /** Where in the branch the new edit goes: the number of edits already in it. */
  readonly position?: number;
  /** What to do with a claim that was drafted and passed the rules. */
  readonly onDrafted?: (drafted: DraftedClaim) => void;
  /**
   * One line about what happens to a claim once it is drafted, in the words of
   * the screen this control is on. Beside a stored map it goes onto the branch;
   * beside a map that has just been generated there is no branch panel yet.
   */
  readonly andThen: string;
  /** How the request is made. The real one by default; a test hands in its own. */
  readonly draft?: typeof draftAClaim;
}

/** *"…but this also happens"*. */
export function AddAClaim({
  baseId,
  position = 0,
  onDrafted,
  andThen,
  draft = draftAClaim,
}: AddAClaimProps) {
  const fieldId = useId();
  const [words, setWords] = useState("");
  const [asking, setAsking] = useState(false);
  const [answer, setAnswer] = useState<Drafted | null>(null);

  return (
    <section className="add-a-claim" aria-label="Add a claim to this map">
      <h3 className="add-a-claim__heading">Add a claim</h3>
      <form
        className="add-a-claim__form"
        onSubmit={(event) => {
          event.preventDefault();
          if (asking || words.trim() === "") {
            return;
          }
          setAsking(true);
          setAnswer(null);
          draft({ base_id: baseId, claim_in_words: words.trim(), position }).then((drafted) => {
            setAsking(false);
            setAnswer(drafted);
            if (drafted.state === "drafted") {
              onDrafted?.(drafted.insert);
            }
          });
        }}
      >
        <label className="add-a-claim__label" htmlFor={fieldId}>
          …but this also happens
        </label>
        <input
          className="add-a-claim__text"
          id={fieldId}
          type="text"
          autoComplete="off"
          placeholder="…but Iran is struck the next day"
          value={words}
          onChange={(event) => setWords(event.target.value)}
        />
        <button className="add-a-claim__ask" type="submit" disabled={asking || words.trim() === ""}>
          {asking ? "Drafting the claim" : "Draft this claim"}
        </button>
      </form>

      {asking ? (
        <p className="add-a-claim__line">
          {/* Not a spinner: the shape of the thing being waited for, said in
              words. One claim is being drafted and checked against this map. */}
          One claim is being drafted and checked against this map, by the same rules every proposal
          passes.
        </p>
      ) : null}

      {answer === null ? null : answer.state === "declined" ? (
        // The server's own sentence, word for word. With no key that is
        // "drafting a new claim needs a model key." and nothing else.
        <p className="add-a-claim__line" data-answer="declined">
          {answer.reason}
        </p>
      ) : answer.state === "refused" ? (
        <div className="add-a-claim__line" data-answer="refused">
          <p className="add-a-claim__refused">
            The map&rsquo;s own rules would not take this claim, and gave every reason at once.
          </p>
          <ul className="add-a-claim__reasons">
            {answer.reasons.map((reason) => (
              <li key={reason}>{reason}</li>
            ))}
          </ul>
        </div>
      ) : (
        <div className="add-a-claim__line" data-answer="drafted">
          <p className="add-a-claim__drafted">
            {`Drafted and checked: "${answer.insert.proposition.claim}" ${andThen}`}
          </p>
          {/* What drafting it cost, in the same nine readings and the same strip
              a generation's receipt is printed in. Absent on a copy of the route
              that does not say yet, and then nothing is invented in its place. */}
          {answer.receipt === null ? null : (
            <ReceiptStrip receipt={answer.receipt} heading="What drafting it cost" />
          )}
        </div>
      )}
    </section>
  );
}

/**
 * The first screen: what you can start from, and the two ways in.
 *
 * No illustration and no empty box staring back. The two doors are named and
 * explained in a line each, the stored example opens a map that is already drawn,
 * and the four sentences from the brief each build one in front of you.
 *
 * **A card has three states and no others.** It runs live, it runs from a
 * recording, or it reads *not yet live* — and that last one now means one thing
 * only: **no model key and no recording**, an example nobody has recorded yet,
 * which is an honest state rather than the catch-all it used to be.
 *
 * **With no key, the four run from recordings through the same route, the same
 * eight events and the same canvas.** The sentence that says so is record 0012's,
 * word for word, and the day in it is read from the server's own readiness answer
 * — never from a file name, never from a build date, never from the browser's own
 * clock. Where the four were not all recorded on one day, the shared sentence
 * names the **oldest** day in the set and each card carries its own, so the
 * sentence is never more current than the oldest thing it describes.
 *
 * **This screen reads what can be replayed and whether a key is configured, and
 * ignores whether the server called itself ready.** A program with no key but
 * four recordings can do everything a reviewer came to see, and a card greyed out
 * because the whole server called itself not ready would be the most misleading
 * screen in the product.
 */

import type { FixtureSummary } from "../api/client";
import type { Readiness } from "../stream/readiness";
import { countInWords } from "../world/naming";
import type { Asked } from "./InputBar";
import { InputBar } from "./InputBar";
import "./launchpad.css";

/** One of the two ways into the tool. */
interface Door {
  readonly name: string;
  readonly line: string;
}

/**
 * The two doors, from the requirements: start from an event and follow it out,
 * or name where you think it ends and ask whether the chain really gets there.
 */
const DOORS: readonly Door[] = [
  {
    name: "Explore",
    line: "Start from an event and see what it would cause, out to the things you could trade.",
  },
  {
    name: "Verify",
    line: "Name where you think it ends, and see whether a chain really gets there — or that none does.",
  },
];

/** One of the four sentences from the brief, and which recording answers to it. */
export interface StartingSentence {
  /**
   * Which stored example this is.
   *
   * It is the name the readiness answer uses for a recording, so that a card can
   * say whether there is one to play. It is **not** a file name and it never
   * reaches a request: what a card sends is its sentence, exactly as a reader
   * would type it, which is what makes the replayed path and the live path send
   * byte-identical requests.
   */
  readonly example: string;
  /** The sentence, as a person would actually type it. */
  readonly sentence: string;
}

/** The four examples from the brief, in the order the brief lists them. */
export const STARTING_SENTENCES: readonly StartingSentence[] = [
  { example: "hormuz", sentence: "The Strait of Hormuz is going to open next week." },
  {
    example: "midterms",
    sentence: "Republicans win the House but Democrats take the Senate during the midterms.",
  },
  {
    example: "export-controls",
    sentence: "Models more capable than Fable get export restricted by the United States.",
  },
  { example: "photonics", sentence: "Photonic chips get adopted faster than expected." },
];

/**
 * Record 0012's sentence, word for word, with the day the readiness answer gave.
 *
 * **It is printed only when it is true**: when all four of the sentences below
 * can be played and all four were recorded on the same day. Anything else and it
 * would be a screen claiming something a reader can see is false — three cards
 * reading *not yet live* under a line saying these four run from recordings — and
 * the one screen this product cannot afford to be caught out on is the one that
 * exists to say what this copy can honestly do.
 *
 * @param day The day the recordings were made.
 */
export function keylessSentence(day: string): string {
  return `No model key configured — these four run from recordings made on ${day}.`;
}

/**
 * What this copy can play, in one or two sentences, and always true.
 *
 * Four shapes, and the first is record 0012's own words. The others say the same
 * kind of thing in the same voice: how many of the four can be played, how many
 * cannot, and the day — the **oldest** day, where there is more than one, so the
 * sentence is never more current than the oldest thing it describes.
 *
 * @param days The day each playable example was recorded on, in any order.
 * @param outOf How many sentences the screen offers altogether.
 */
export function whatThisCopyCanPlay(days: readonly string[], outOf: number): string | null {
  if (days.length === 0) {
    return null;
  }
  const sorted = [...days].sort();
  const oldest = sorted[0] as string;
  const allOfThem = days.length === outOf;
  const oneDay = sorted[sorted.length - 1] === oldest;

  if (allOfThem && oneDay) {
    return keylessSentence(oldest);
  }
  if (allOfThem) {
    return (
      `No model key configured — these ${countInWords(outOf)} run from recordings, the oldest ` +
      `made on ${oldest}.`
    );
  }
  const rest = outOf - days.length;
  const canPlay = days.length === 1 ? "runs" : "run";
  const cannot = rest === 1 ? "has" : "have";
  const theRest = rest === 1 ? "the other one" : `the other ${countInWords(rest)}`;
  const when = oneDay ? `made on ${oldest}` : `the oldest made on ${oldest}`;
  return (
    `No model key configured — ${countInWords(days.length)} of these ${countInWords(outOf)} ` +
    `${canPlay} from recordings, ${when}; ${theRest} ${cannot} nothing recorded yet.`
  );
}

/** What each card can do, which is one of exactly three things. */
type CardState = "live" | "replay" | "not-yet";

/** What the launchpad needs to draw itself. */
export interface LaunchpadProps {
  /**
   * The stored examples the server ships with, or null while the answer is still
   * on its way.
   */
  readonly examples: readonly FixtureSummary[] | null;
  /** Why the list could not be read, if it could not be. */
  readonly failure: string | null;
  /**
   * What the server said about itself: whether a key is configured, and what it
   * can play back. Null while that answer is still on its way.
   */
  readonly readiness: Readiness | null;
  /** Open a stored example's map, already drawn. */
  readonly onOpen: (id: string) => void;
  /** Build a map from a sentence. */
  readonly onBuild: (asked: Asked) => void;
}

/** The first screen. */
export function Launchpad({ examples, failure, readiness, onOpen, onBuild }: LaunchpadProps) {
  // The two facts this screen reads, and the one it deliberately does not.
  const hasKey = readiness?.model_key_present === true;
  const recorded = new Map(
    (readiness?.replayable ?? []).map((one) => [one.example, one.recording_date]),
  );
  // The day each of the four sentences was recorded on, for the ones that were.
  // Read off the cards rather than off the whole answer, so a recording of
  // something this screen does not offer cannot make its sentence wrong.
  const playable = STARTING_SENTENCES.map((one) => recorded.get(one.example)).filter(
    (day): day is string => day !== undefined,
  );
  const canPlay = whatThisCopyCanPlay(playable, STARTING_SENTENCES.length);
  const stateOf = (example: string): CardState =>
    hasKey ? "live" : recorded.has(example) ? "replay" : "not-yet";

  return (
    <div className="launchpad">
      <section className="launchpad__doors" aria-labelledby="doors-heading">
        <h2 className="section-heading" id="doors-heading">
          Two ways in
        </h2>
        <ul className="doors">
          {DOORS.map((door) => (
            <li className="door" key={door.name}>
              <span className="door__name">{door.name}</span>
              <span className="door__line">{door.line}</span>
            </li>
          ))}
        </ul>
      </section>

      <section className="launchpad__drawn" aria-labelledby="examples-heading">
        <h2 className="section-heading" id="examples-heading">
          A map that is already drawn
        </h2>
        <ul className="examples">
          {examples === null ? (
            <li className="example example--waiting">
              <span className="example__claim">
                {failure ?? "Asking the server which examples it ships with."}
              </span>
              {failure === null ? <span className="placeholder" aria-hidden="true" /> : null}
            </li>
          ) : (
            examples.map((example) => (
              <li key={example.id}>
                <button
                  className="example example--live"
                  type="button"
                  onClick={() => onOpen(example.id)}
                >
                  <span className="example__claim">{example.title}</span>
                  <span className="example__line">{example.one_line}</span>
                  <span className="example__action">Open the map</span>
                </button>
              </li>
            ))
          )}
        </ul>
      </section>

      <section className="launchpad__build" aria-labelledby="build-heading">
        <h2 className="section-heading" id="build-heading">
          Or watch one build itself
        </h2>
        <ul className="examples">
          {STARTING_SENTENCES.map((one) => {
            const state = stateOf(one.example);
            const day = recorded.get(one.example);
            return (
              <li key={one.example}>
                {state === "not-yet" ? (
                  <div className="example example--waiting" data-state="not-yet">
                    <span className="example__claim">{one.sentence}</span>
                    <span className="example__line">
                      Would be turned into a map of what it causes, ending in trades.
                    </span>
                    <span className="example__action example__action--waiting">
                      <span className="example__badge">not yet live</span>
                      no model key, and nothing recorded for this one
                    </span>
                  </div>
                ) : (
                  <button
                    className="example example--live"
                    type="button"
                    data-state={state}
                    onClick={() =>
                      onBuild({ hypothesis: one.sentence, target: null, belief: null })
                    }
                  >
                    <span className="example__claim">{one.sentence}</span>
                    <span className="example__line">
                      {state === "replay"
                        ? "Plays the recording of this run back, claim by claim, through the same route and the same canvas."
                        : "Builds a map of what it would cause, claim by claim, ending in trades."}
                    </span>
                    {/* Not **Build the map**: that is the one button on the
                        input bar, and a word that names two controls names
                        neither. A card is a sentence somebody already typed. */}
                    <span className="example__action">
                      {state === "replay" ? (
                        <>
                          <span className="example__badge">replay</span>
                          {day === undefined ? "Watch it build" : `recorded ${day}`}
                        </>
                      ) : (
                        "Watch it build"
                      )}
                    </span>
                  </button>
                )}
              </li>
            );
          })}
        </ul>

        {/* Record 0012's sentence, word for word, under the four cards — and
            again under the field below, which is disabled with it. */}
        {canPlay === null || hasKey ? null : <p className="launchpad__keyless">{canPlay}</p>}
        {/* What *not yet live* means, said once in full rather than three times
            over: each card carries the short form, and this is the whole of it.
            It is the honest state now, not a catch-all — a key would run it, and
            a recording would play it, and this copy has neither. */}
        {hasKey || STARTING_SENTENCES.every((one) => recorded.has(one.example)) ? null : (
          <p className="launchpad__keyless launchpad__keyless--quiet">
            A card reads <b>not yet live</b> when this copy has no model key and nobody has recorded
            that example, so there is nothing it could honestly show you.
          </p>
        )}
      </section>

      {/* A sentence of the reader's own. It is a section of its own rather than
          a footnote under the four cards, because typing your own event is the
          way in this product is for and the four are the shortcut. */}
      <section className="launchpad__yours" aria-labelledby="yours-heading">
        <h2 className="section-heading" id="yours-heading">
          Or start from a sentence of your own
        </h2>
        <InputBar
          disabledBecause={
            hasKey
              ? null
              : canPlay === null
                ? "This copy has no model key and no recordings, so a sentence of your own cannot be turned into a map."
                : `${canPlay} A sentence of your own needs the model, and there is no recording of one.`
          }
          onBuild={onBuild}
        />
      </section>
    </div>
  );
}

/**
 * What a generation cost, printed exactly as the engine sent it.
 *
 * **Every line is a field.** This file does not add the two token counts
 * together, does not work a cost out of a token count and a price, and does not
 * time anything. The price table lives in one module on the server with the day
 * it was read beside it, and the dollars here came from there.
 *
 * **Web searches are a row of their own** because they are billed apart from
 * tokens: without that row, the cost is a number a reader could check against the
 * token counts and find wrong.
 *
 * **Before the receipt arrives there is no strip.** No running estimate, no
 * ticking cost, no progress bar. A cost nobody has totalled is a number nobody
 * computed, and a percentage nobody computed is a number nobody computed wearing
 * a progress bar.
 *
 * **The two-significant-figures rule is about likelihoods.** A token count, a
 * call count, a duration and a dollar figure are counts and measurements: they
 * are printed whole, in the number face with fixed-width digits, and they carry
 * no range because nothing sampled them.
 *
 * The same nine lines are drawn in two places — here, beside a growing map, and
 * in the panel's own section for the run that produced the map. They are one
 * component so the two cannot drift.
 */

import type { Receipt } from "../stream/events";
import "./receiptStrip.css";

/** A whole count, spaced in threes so a six-figure token count can be read. */
function asCount(value: number): string {
  return value.toLocaleString("en-GB").replace(/,/g, " ");
}

/**
 * A measurement, rounded for the page and never for the arithmetic.
 *
 * Rounding here is a display decision made at the moment of printing, the same
 * decision a belief chip makes — the value itself is carried at whatever
 * precision it arrived with and nothing downstream reads this string.
 */
function asMeasurement(value: number, least: number, most: number): string {
  return value.toLocaleString("en-GB", {
    minimumFractionDigits: least,
    maximumFractionDigits: most,
  });
}

/** One labelled reading off the receipt. */
interface Line {
  /** What it is, in the reader's words. */
  readonly label: string;
  /** The reading, already turned into the characters that go on screen. */
  readonly reading: string;
  /** The name of the field it came from, for a reader asking where it is from. */
  readonly field: string;
}

/**
 * The nine readings a receipt carries, in the order they are printed.
 *
 * Nine, always, and none of them derived. A receipt with a field left out is a
 * receipt somebody would have to reconstruct.
 *
 * @param receipt The receipt event, exactly as it arrived.
 */
export function receiptLines(receipt: Receipt): readonly Line[] {
  return [
    { label: "model", reading: receipt.model, field: "model" },
    { label: "calls", reading: asCount(receipt.calls), field: "calls" },
    { label: "tokens in", reading: asCount(receipt.input_tokens), field: "input_tokens" },
    { label: "tokens out", reading: asCount(receipt.output_tokens), field: "output_tokens" },
    {
      label: "read from cache",
      reading: asCount(receipt.cache_read_tokens),
      field: "cache_read_tokens",
    },
    { label: "web searches", reading: asCount(receipt.searches), field: "searches" },
    // Money prints as money: two places at the least and four at the most, so a
    // run that spent nothing reads $0.00 and one that spent a third of a penny
    // still says so.
    { label: "cost", reading: `$${asMeasurement(receipt.dollars, 2, 4)}`, field: "dollars" },
    { label: "took", reading: `${asMeasurement(receipt.seconds, 1, 1)}s`, field: "seconds" },
    { label: "mode", reading: modeLine(receipt), field: "mode" },
  ];
}

/**
 * What the mode line says.
 *
 * In a replay it names the day the recording was made and the prompt it was made
 * against, because those are the two things that say which run this is a picture
 * of. Live, there is no recording and no day, so it says only what it is.
 */
function modeLine(receipt: Receipt): string {
  if (receipt.mode === "live") {
    return `live · prompt ${receipt.prompt_hash.slice(0, 8)}`;
  }
  const day = receipt.recording_date;
  return day === null
    ? `replay · prompt ${receipt.prompt_hash.slice(0, 8)}`
    : `replay · recorded ${day} · prompt ${receipt.prompt_hash.slice(0, 8)}`;
}

/** What the strip needs to draw itself. */
export interface ReceiptStripProps {
  /** The receipt event, exactly as it arrived. */
  readonly receipt: Receipt;
  /** What this heading is called, so the panel and the strip can title it their own way. */
  readonly heading?: string;
  /** Open the working of the run. Left out, the strip is read-only. */
  readonly onOpen?: () => void;
}

/** The nine labelled readings, and nothing else. */
export function ReceiptLines({ receipt }: { receipt: Receipt }) {
  return (
    <dl className="receipt-strip__lines">
      {receiptLines(receipt).map((line) => (
        <div className="receipt-strip__line" key={line.field} data-field={line.field}>
          <dt className="receipt-strip__label">{line.label}</dt>
          <dd className="receipt-strip__reading">{line.reading}</dd>
        </div>
      ))}
    </dl>
  );
}

/** What the run cost, beside the map it produced. */
export function ReceiptStrip({ receipt, heading = "This generation", onOpen }: ReceiptStripProps) {
  return (
    <section className="receipt-strip" aria-label="What this generation cost">
      <h3 className="receipt-strip__heading">{heading}</h3>
      <ReceiptLines receipt={receipt} />
      {receipt.mode === "replay" ? (
        <p className="receipt-strip__note">
          This run played a recording back, so nothing was called and nothing was spent. That zero
          is a zero somebody worked out, printed rather than hidden.
        </p>
      ) : null}
      {onOpen === undefined ? null : (
        <button className="receipt-strip__open" type="button" onClick={onOpen}>
          Read the working of this run
        </button>
      )}
    </section>
  );
}

/**
 * The Verify door's answer: a graded route to the place a reader asked about, or
 * an honest statement that nothing on the map reaches it.
 *
 * The two are not a success and a failure. **"No path reaches this" is the most
 * valuable thing this door can tell you**, so it is drawn as a finding, in the
 * engine's own sentence, with the nearest claim the map did reach named and one
 * control that selects it.
 *
 * **No bridge is drawn. Ever.** No dotted arrow from the nearest claim to the
 * destination, no ghost tile for it, no "probably connects" wording. Drawing a
 * faint one would be a fabrication in the exact place the honesty bar exists to
 * prevent one.
 *
 * **Nothing here multiplies anything.** The route's likelihood arrives on the
 * verdict, worked out where the map's numbers are worked out, and this card
 * prints it. When there is none the slot says so with its reason.
 */

import type { Verdict } from "../stream/events";
import type { WorldView } from "../world";
import { countInWords, NOT_ON_THIS_MAP } from "../world/naming";
import { toTwoFigures } from "./BeliefChip";
import { PATH_PRODUCT_WART } from "./PathBar";
import "./verdictCard.css";

/** What the card needs to draw itself. */
export interface VerdictCardProps {
  /** The engine's answer, exactly as it arrived. */
  readonly verdict: Verdict;
  /** The destination in the reader's own words, as they typed it. */
  readonly target: string;
  /** The map, so a step can be named by its claim rather than by its identifier. */
  readonly world: WorldView;
  /** Put the panel and the map on one claim. */
  readonly onSelect?: (claimId: string) => void;
}

/** How long the route is, in words: *two steps from the hypothesis*. */
function howLong(claims: number): string {
  const steps = Math.max(0, claims - 1);
  return `${countInWords(steps)} ${steps === 1 ? "step" : "steps"} from the hypothesis`;
}

/** The Verify door's answer, in whichever of its two shapes arrived. */
export function VerdictCard({ verdict, target, world, onSelect }: VerdictCardProps) {
  const words = new Map(world.claims.map((claim) => [claim.id, claim.claim]));

  if (verdict.kind === "no_path") {
    const nearest = verdict.nearest;
    return (
      <section className="verdict-card" data-kind="no_path" aria-label="Where you said it ends">
        <h3 className="verdict-card__heading">No path reaches this</h3>
        <p className="verdict-card__target">{target}</p>
        {/* The engine's own plain sentence, printed as it came. This file
            composes no sentence about a verdict. */}
        <p className="verdict-card__why">{verdict.why}</p>
        {nearest === null ? null : (
          <p className="verdict-card__nearest">
            <span className="verdict-card__label">nearest claim reached</span>
            {/* Named by its words, never by its identifier — the same rule the
                validator's own sentences obey. A claim this map does not hold is
                a claim this card has nothing to point at, and it says so rather
                than printing a name nobody reads. */}
            {words.has(nearest) ? (
              <button
                className="verdict-card__pick"
                type="button"
                onClick={() => onSelect?.(nearest)}
              >
                {words.get(nearest)}
              </button>
            ) : (
              <span className="verdict-card__note">
                The engine named a claim this screen is not drawing, so there is nothing here to
                point at.
              </span>
            )}
          </p>
        )}
        <p className="verdict-card__note">
          Nothing is drawn between that claim and where you said it ends, because nothing on this
          map joins them. A faint arrow suggesting one might would be exactly the invention this
          product exists to refuse.
        </p>
      </section>
    );
  }

  return (
    <section className="verdict-card" data-kind="reached" aria-label="Where you said it ends">
      <h3 className="verdict-card__heading">The story reaches this</h3>
      <p className="verdict-card__target">{target}</p>
      <p className="verdict-card__why">{verdict.why}</p>

      {/* How long the route is, and then the route itself — one claim per row,
          named by its own words and numbered by where it sits. **No identifier
          is printed**: on a generated map they are twenty-six characters of the
          engine's own bookkeeping, and a reader learns nothing from one. */}
      <p className="verdict-card__route">{howLong(verdict.path.length)}</p>
      <ol className="verdict-card__steps">
        {verdict.path.map((id, place) => (
          <li className="verdict-card__step" key={id}>
            <button className="verdict-card__pick" type="button" onClick={() => onSelect?.(id)}>
              <span className="verdict-card__step-id">{place === 0 ? "start" : place}</span>
              <span className="verdict-card__step-claim">{words.get(id) ?? NOT_ON_THIS_MAP}</span>
            </button>
          </li>
        ))}
      </ol>

      <p className="verdict-card__label">path likelihood</p>
      {verdict.product === null ? (
        <>
          <p className="verdict-card__reading" data-reading="no-number">
            no engine yet
          </p>
          <p className="verdict-card__note">
            The steps of this route have not been worked through the map, so there is no number to
            multiply out. Nothing here would work one out.
          </p>
        </>
      ) : (
        <p className="verdict-card__reading" data-reading="number">
          {toTwoFigures(verdict.product)}
        </p>
      )}
      {/* One wording, written where the path bar writes it. */}
      <p className="verdict-card__note">{PATH_PRODUCT_WART}</p>
    </section>
  );
}

/**
 * The mark saying this session is playing a recording back.
 *
 * It is a fact about the **session**, not a badge on a claim, and it is on screen
 * from the moment the run starts — long before the receipt that also says so
 * arrives. That is the whole reason it exists twice: the browser knows there is
 * no model key before the stream has said anything, and a reader should not watch
 * a map build itself for a minute before being told where it came from.
 *
 * **It is a badge, and it sits beside the title.** It used to be a paragraph
 * floating over the canvas, which was wrong twice: nothing in this product may
 * sit over the map, and on a real ten-claim map it covered tiles. So the mark is
 * a word and a day, up in the bar with the map's name, and the sentence that
 * explains it goes in the line under the map where every other sentence about
 * where this map came from already lives.
 *
 * **Two sources, and the receipt is the authority.** The badge is set from
 * whether a key is configured; the receipt, when it lands, carries the mode and
 * the day the recording was made. The receipt names the day here, and if it ever
 * says *live* where this badge says *replay*, the badge takes the receipt's word
 * and says out loud that the two disagreed. Two derivations of one line are
 * normally the thing this product refuses; this is the one place both are needed,
 * so the rule is written down rather than left to luck.
 */

import "./replayBadge.css";

/** What the badge needs to draw itself. */
export interface ReplayBadgeProps {
  /**
   * The day the recording was made, as the receipt reported it, or null before
   * the receipt has arrived. Never the browser's own clock and never a file name.
   */
  readonly recordingDate: string | null;
  /**
   * What the receipt says this run was, or null before it arrives. When it says
   * `live` and this badge is on screen, the two disagree and the badge says so.
   */
  readonly receiptMode: "live" | "replay" | null;
}

/** Whether the badge and the receipt disagree about what this run was. */
function theyDisagree(receiptMode: ReplayBadgeProps["receiptMode"]): boolean {
  return receiptMode === "live";
}

/**
 * The sentence that explains the badge, for the line under the map.
 *
 * It is written here, beside the badge it explains, so the two cannot drift —
 * and it is printed there rather than on the canvas, because nothing in this
 * product sits over the map.
 */
export function replaySentence({ recordingDate, receiptMode }: ReplayBadgeProps): string {
  if (theyDisagree(receiptMode)) {
    return (
      "This session has no model key, so it played a recording — but the receipt says the run " +
      "was live. The receipt is the authority, and the two disagreeing is itself worth seeing."
    );
  }
  const from =
    recordingDate === null
      ? "The receipt will name the day it was made."
      : `It was made on ${recordingDate}.`;
  return (
    "No model key is configured, so this map is a recording being played back through the same " +
    `route, the same events and the same canvas. ${from}`
  );
}

/** The mark beside the map's name: one word, and the day. */
export function ReplayBadge({ recordingDate, receiptMode }: ReplayBadgeProps) {
  const disagreed = theyDisagree(receiptMode);
  return (
    <span className="replay-badge" data-disagreed={disagreed ? "yes" : "no"}>
      <span className="replay-badge__word">replay</span>
      {recordingDate === null ? null : <span className="replay-badge__day">{recordingDate}</span>}
      {/* Said out loud for a reader who is not looking at the bar. The same
          sentence is printed in full under the map. */}
      <span className="replay-badge__spoken">{replaySentence({ recordingDate, receiptMode })}</span>
    </span>
  );
}

/**
 * Why the generation stopped, in the engine's words for each reason — and, when
 * something broke instead, the one plain sentence it left.
 *
 * **One reason arrives, never a list**, and it names what closed the last claim
 * that was still open, with the spending limit and the no-ending case overriding
 * everything above them.
 *
 * Two things the seven sentences do on purpose. **No sentence blames the model
 * for our own rules**: three refusals in a row is our validator turning proposals
 * down and our cap deciding that three is enough, and a sentence reading *"the
 * model stopped answering"* would be a screen accusing a third party of a
 * decision we took. And **each one names the cap and not its value**, because the
 * stream carries no value — a limit printed from memory would be a number nobody
 * on this screen computed, and a limit that had quietly changed on the server
 * would then be a number that was wrong.
 */

import type { Done, StopReason } from "../stream/events";
import "./doneLine.css";

/** What the strip says for each of the seven reasons a run can stop. */
export const WHY_IT_STOPPED: Record<StopReason, string> = {
  reached_terminal:
    "The last line closed properly: it reached something you could trade, or a stated reason " +
    "there is nothing to trade, or the model had nothing more to add.",
  depth_cap:
    "The last line still open ran as far from your sentence as one generation goes, and stopped " +
    "there.",
  width_cap:
    "The last line still open was closed because that claim already has every effect one " +
    "generation draws from it.",
  claim_cap: "The last line still open was closed because the map was full.",
  spend_cap:
    "The run reached its spending limit and stopped where it was. The receipt says what it spent.",
  refusal_cap: "One line was abandoned: three proposals in a row for it were refused.",
  no_terminal:
    "One last call asked every open claim where it ends, and none of them ends in something you " +
    "could trade.",
};

/** What the line needs to draw itself. */
export interface DoneLineProps {
  /** The closing event, when the run closed. */
  readonly done: Done | null;
  /** The one sentence a broken run left, when one broke. */
  readonly failure: string | null;
}

/** Why the run ended, said once, under the map. */
export function DoneLine({ done, failure }: DoneLineProps) {
  if (failure !== null) {
    return (
      <p className="done-line" data-kind="failed">
        <span className="done-line__word">stopped</span>
        {/* One plain sentence, never a stack trace. The map that had been built
            stays exactly where it is: a reader whose run broke after twenty
            claims keeps the twenty claims. */}
        <span className="done-line__why">{failure}</span>
      </p>
    );
  }
  if (done === null) {
    return null;
  }
  return (
    <p className="done-line" data-kind={done.reason}>
      <span className="done-line__word">finished</span>
      <span className="done-line__why">{WHY_IT_STOPPED[done.reason]}</span>
      <span className="done-line__counts">
        {`${done.claims} claims · ${done.links} arrows · ${done.rejected} refused`}
      </span>
    </p>
  );
}

/**
 * A reserved rectangle standing where a claim is about to arrive.
 *
 * **Not a shimmer, not a pulse, not a grey bar sliding across a card.** A space
 * held open, at the size and in the place the thing being waited for will take.
 * An animated placeholder is a tool performing busyness at a reader who is
 * waiting on a model call that takes half a minute; a held rectangle is a tool
 * saying where the next thing goes.
 *
 * **It is never a claim.** It has no identifier on the map — its name is a box's
 * name — it never reaches the network, it carries no likelihood, and there is no
 * number on it to be a number nobody computed, because there is no number on it
 * at all. The only thing it prints is one line the stream carried: the reader's
 * own sentence, or the words of the open claim it hangs off.
 *
 * Its box is a tile's box: 280 pixels wide and 152 tall, which is the floor of a
 * tile's own clamped height — so when the claim lands, it lands at least as tall
 * as the rectangle that was held for it and nothing above it moves.
 */

import { TILE_MIN_HEIGHT, TILE_WIDTH } from "../graph/geometry";
import "./skeletonTile.css";

/** What a reserved rectangle needs to draw itself. */
export interface SkeletonTileProps {
  /**
   * The one line it carries — the reader's own sentence, or *one step on from
   * "…"*, quoting the open claim this rectangle hangs off.
   *
   * Every character of it came off the stream or out of the reader's own typing.
   * Nothing here composes a sentence.
   */
  readonly words: string;
}

/** One reserved rectangle. */
export function SkeletonTile({ words }: SkeletonTileProps) {
  return (
    <div
      className="skeleton-tile"
      style={{ width: `${TILE_WIDTH}px`, height: `${TILE_MIN_HEIGHT}px` }}
    >
      {/* What the box is, in real words rather than in a label written for a
          reader who cannot see it — so the two readings are the same reading,
          and neither can drift from the other. */}
      <span className="skeleton-tile__mark">held open</span>
      <p className="skeleton-tile__words">{words}</p>
    </div>
  );
}

