1	/**
2	 * The motion budget: three moves, and everything else is an opacity change.
3	 *
4	 * The three are the propagation wave — the wires arriving in the order the
5	 * argument runs — a branch arriving, and a likelihood rolling from an old figure
6	 * to a new one. Everything else that appears or goes does so with an opacity
7	 * change of at most 120 milliseconds, and nothing at all loops, spins or sweeps.
8	 *
9	 * **Growth spends what is already budgeted and adds nothing.** A map building
10	 * itself is the case the wave was written for; a reserved rectangle appears and
11	 * goes with the ordinary 120 milliseconds of opacity. There is no fourth
12	 * animation, and a fourth would be the one that turns a budget into a
13	 * suggestion.
14	 *
15	 * Under reduced motion **the ordering survives and the tweening goes**. That is
16	 * the load-bearing half: the gap between one column of the map and the next is
17	 * the order the argument runs in, so it stays at sixty milliseconds while every
18	 * in-between frame goes to nothing.
19	 */
20	
21	import { readdirSync, readFileSync, statSync } from "node:fs";
22	import { join } from "node:path";
23	import { describe, expect, it } from "vitest";
24	
25	/** Every stylesheet in the tree, by the path the rules below name it by. */
26	function everyStylesheet(from: string): Record<string, string> {
27	  const found: Record<string, string> = {};
28	  for (const name of readdirSync(from)) {
29	    const path = join(from, name);
30	    if (statSync(path).isDirectory()) {
31	      Object.assign(found, everyStylesheet(path));
32	    } else if (name.endsWith(".css")) {
33	      found[`/${path.replaceAll("\\", "/")}`] = readFileSync(path, "utf8");
34	    }
35	  }
36	  return found;
37	}
38	
39	const STYLESHEETS = everyStylesheet("src");
40	const TOKENS = STYLESHEETS["/src/styles/tokens.css"] ?? "";
41	
42	/**
43	 * The tokens a duration may be spelled with, and what each is for.
44	 *
45	 * A raw number of milliseconds anywhere else is a fourth duration nobody agreed
46	 * to, so the check is that every duration in the product is one of these names.
47	 */
48	const THE_ONLY_DURATIONS = ["--duration-fast", "--duration-wave", "--duration-stagger"];
49	
50	describe("the motion budget", () => {
51	  it("test_no_duration_above_120ms_outside_the_three_budgeted_moves", () => {
52	    // The three tokens, and the values they are set to in one place.
53	    expect(TOKENS).toContain("--duration-fast: 120ms");
54	    expect(TOKENS).toContain("--duration-wave: 200ms");
55	    expect(TOKENS).toContain("--duration-stagger: 60ms");
56	
57	    const wrong: string[] = [];
58	    for (const [path, whole] of Object.entries(STYLESHEETS)) {
59	      // A check that silently walks nothing is a check that always passes.
60	      expect(whole.length).toBeGreaterThan(0);
61	
62	      // The rules, without the prose around them. Half these files explain in so
63	      // many words what each duration is for, and a check that read the prose
64	      // would punish saying so.
65	      const sheet = whole.replaceAll(/\/\*[\s\S]*?\*\//g, " ");
66	
67	      // Where a duration is *set*, it is set in tokens.css and nowhere else.
68	      // Everywhere else spends one of the three by name.
69	      for (const spent of sheet.matchAll(/(animation|transition)[^;{]*:[^;}]*/g)) {
70	        const said = spent[0];
71	        if (!THE_ONLY_DURATIONS.some((token) => said.includes(token))) {
72	          wrong.push(`${path}: ${said.trim().replace(/\s+/g, " ")} spends no budgeted duration`);
73	        }
74	      }
75	
76	      // And no raw duration is written down anywhere outside the tokens. A zero
77	      // is not a duration: it is the absence of one, and it is what a delay
78	      // starts at before a column's own stagger is added to it.
79	      if (path !== "/src/styles/tokens.css") {
80	        for (const raw of sheet.matchAll(/\b\d+m?s\b/g)) {
81	          if (raw[0] !== "0ms" && raw[0] !== "0s") {
82	            wrong.push(`${path}: writes the duration ${raw[0]} down rather than spending a token`);
83	          }
84	        }
85	      }
86	    }
87	    expect(wrong).toEqual([]);
88	  });
89	
90	  it("test_reduced_motion_zeroes_every_tween_and_keeps_the_stagger", () => {
91	    // The tweening goes and the ordering stays. The gap between one column of
92	    // the map and the next is the order the argument runs in — the ordering is
93	    // the causality, and removing it would remove the one thing the movement was
94	    // for.
95	    const reduced = TOKENS.slice(TOKENS.indexOf("prefers-reduced-motion"));
96	    expect(reduced).toContain("--duration-fast: 0ms");
97	    expect(reduced).toContain("--duration-wave: 0ms");
98	    expect(reduced).not.toContain("--duration-stagger: 0ms");
99	  });
100	});
101

